# ---- Themes (v1.1.40) -----------------------------------------------------------
# Every colour in the program is written as one of the original dark-theme hex
# values. Those values are keys: each one has a role (background, text, status
# colour, button fill, accent, fixed scanner colour), and the current theme works
# out what each key looks like in Dark, Light or Night mode with the chosen accent.
# All stylesheets, colours, rich text and chart fonts go through set_css(), tc(),
# set_text()/make_label() and tf(), so a theme change can re-apply them live.
import colorsys

THEME_MODES = {"dark": "Dark", "light": "Light", "system": "System (follow KDE)",
               "night": "Night (red)"}
THEME_ACCENTS = {"blue": ("Blue", 210), "red": ("Red", 0), "green": ("Green", 140),
                 "amber": ("Amber", 38), "purple": ("Purple", 275), "teal": ("Teal", 178)}
TEXT_SIZES = {"small": ("Small", 0.86), "normal": ("Normal", 1.0),
              "large": ("Large", 1.15), "xlarge": ("Extra large", 1.3)}
# The Scanner Screen mirror shows the scanner's own display colours.
FIXED_COLOURS = {"#000000", "#05080d", "#111111", "#0d1d3a", "#f0f0f0", "#f4f4f0",
                 "#f2f6ff", "#8fa3ba"}
# Coloured button backgrounds with white text: kept as they are in Light.
FILL_COLOURS = {"#344d71", "#536779", "#566476", "#7654a6", "#8a3b3b", "#263849",
                "#435c77", "#1b8a5a", "#a87d15", "#bd6b23", "#9c3b2e", "#a83232",
                "#5b4a1e", "#7d6420", "#a5841f", "#2f9e62", "#39424e", "#1c2028"}
ACCENT_FILLS = {"#2167b1", "#344d71", "#245b91", "#2975b8", "#426789"}
ACCENT_LINES = {"#69b8ef", "#76d5f4", "#83c3e9", "#85dcff", "#69a8d6", "#6d9fc6",
                "#567c9f", "#dceeff", "#3d8fd6"}
ON_FILL = {"#ffffff"}
LIGHT_BG = (0.85, 0.865, 0.88)          # darkest Light panel text sits on (buttons, headers)
HEX_RE = re.compile(r"#[0-9a-fA-F]{6}\b")
FONT_PX_RE = re.compile(r"(font-size:\s*)(\d+(?:\.\d+)?)px")
WHITE_RE = re.compile(r"(color:\s*)white\b")


def _rgb(hexkey):
    return tuple(int(hexkey[i:i + 2], 16) / 255 for i in (1, 3, 5))


def _hex(r, g, b):
    return "#" + "".join(f"{max(0, min(255, round(v * 255))):02x}" for v in (r, g, b))


def _lum(rgb):
    def ch(c):
        return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = (ch(c) for c in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def contrast(a, b):
    la, lb = _lum(a), _lum(b)
    return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)


def colour_role(key):
    if key in FIXED_COLOURS:
        return "fixed"
    if key in ON_FILL:
        return "onfill"
    if key in ACCENT_FILLS:
        return "afill"
    if key in ACCENT_LINES:
        return "aline"
    if key in FILL_COLOURS:
        return "fill"
    h, l, s = colorsys.rgb_to_hls(*_rgb(key))
    hue = h * 360
    if l < 0.45 and s < 0.45:
        return "surface"
    if l < 0.5:
        return "fill"
    if s < 0.3 or l > 0.9 or (s < 0.45 and 195 <= hue <= 235):
        return "text"
    return "status"


class Theme:
    def __init__(self, mode="dark", accent="blue", size="normal", system_dark=True):
        self.choice = mode if mode in THEME_MODES else "dark"
        self.mode = ({"system": "dark" if system_dark else "light"}.get(self.choice,
                                                                         self.choice))
        self.accent = accent if accent in THEME_ACCENTS else "blue"
        self.size = size if size in TEXT_SIZES else "normal"
        self.scale = TEXT_SIZES[self.size][1]
        self.cache, self.reverse = {}, {}

    @property
    def identity(self):
        return self.mode == "dark" and self.accent == "blue"

    def colour(self, key):
        """Theme value of one colour key ('#rrggbb'); anything else unchanged."""
        if not isinstance(key, str) or not HEX_RE.fullmatch(key.strip()):
            return key
        key = key.strip().lower()
        out = self.cache.get(key)
        if out is None:
            out = key if self.identity else self.transform(key)
            self.cache[key] = out
            self.reverse.setdefault(out, key)
        return out

    def transform(self, key):
        role = colour_role(key)
        rgb = _rgb(key)
        if self.mode == "night":
            return self.night(rgb, role)
        h, l, s = colorsys.rgb_to_hls(*rgb)
        hue = h * 360
        if self.accent != "blue" and (role in ("afill", "aline")
                                      or (role in ("surface", "text") and 195 <= hue <= 235)):
            hue = (hue + THEME_ACCENTS[self.accent][1] - 210) % 360
            if role in ("surface", "text"):
                s *= 0.55
            elif role == "afill":
                # Same brightness as the blue it replaces, so white text stays readable
                # (green, teal and amber are much brighter than blue at equal lightness).
                target = _lum(rgb)
                while l > 0.05 and _lum(colorsys.hls_to_rgb(hue / 360, l, s)) > target:
                    l -= 0.01
        if self.mode == "light":
            if role == "surface":
                l = max(0.6, min(0.985, 0.97 - (l - 0.09) * 0.9))
                s *= 0.7
            elif role == "text":
                l = min(0.34, (1 - l) * 1.3)
                s = min(s, 0.5)
            elif role in ("status", "aline"):
                s = max(s, 0.55) if s > 0.2 else s
                target = 4.5 if role == "status" else 3.0
                while l > 0.05 and contrast(colorsys.hls_to_rgb(hue / 360, l, s),
                                            LIGHT_BG) < target:
                    l -= 0.01
        return _hex(*colorsys.hls_to_rgb(hue / 360, l, s))

    @staticmethod
    def night(rgb, role):
        """Night: every colour becomes a shade of red by its brightness."""
        y = _lum(rgb)
        if role == "surface":
            l, s = 0.42 * y ** 0.5, 0.55
        elif role in ("fill", "afill"):
            l, s = 0.40 * y ** 0.5, 0.7
        else:
            l, s = 0.25 + 0.25 * y ** 0.5, 1.0
        return _hex(*colorsys.hls_to_rgb(0, l, s))

    def css(self, text):
        if not isinstance(text, str):
            return text
        if not self.identity:
            text = WHITE_RE.sub(lambda m: m.group(1) + "#ffffff", text)
        # Always through colour(), so the colours in use are known for a change.
        text = HEX_RE.sub(lambda m: self.colour(m.group()), text)
        if self.scale != 1.0:
            text = FONT_PX_RE.sub(
                lambda m: f"{m.group(1)}{max(7, round(float(m.group(2)) * self.scale))}px",
                text)
        return text


THEME = Theme()


def theme_hex(key):
    return THEME.colour(key)


def th(css):
    """A stylesheet in the current theme."""
    return THEME.css(css)


def thtml(text):
    """Rich text in the current theme (plain text is left alone)."""
    if isinstance(text, str) and "<" in text and "#" in text:
        return THEME.css(text)
    return text


def tc(*args):
    """QColor in the current theme: tc('#7ee3a5'); other forms as QColor()."""
    if len(args) == 1 and isinstance(args[0], str):
        return QColor(THEME.colour(args[0]))
    return QColor(*args)


def tf(family, size=None, *rest):
    """QFont for painted text, scaled to the text size setting."""
    if isinstance(size, (int, float)):
        return QFont(family, max(6, round(size * THEME.scale)), *rest)
    if size is None:
        return QFont(family)
    return QFont(family, size, *rest)


def set_css(widget, css):
    """setStyleSheet() through the theme; the original is kept for theme changes."""
    try:
        widget.setProperty("themeCss", css)
    except (AttributeError, TypeError):
        pass
    widget.setStyleSheet(th(css))


def set_text(widget, text):
    """setText() through the theme: rich text is kept so its colours can change."""
    if isinstance(text, str) and "<" in text and "#" in text and hasattr(widget, "setProperty"):
        widget.setProperty("themeHtml", text)
        widget.setText(thtml(text))
        return
    if hasattr(widget, "property") and widget.property("themeHtml") is not None:
        widget.setProperty("themeHtml", None)
    widget.setText(text)


def make_label(*args, **kwargs):
    if args and isinstance(args[0], str):
        label = QLabel("", *args[1:], **kwargs)
        set_text(label, args[0])
        return label
    return QLabel(*args, **kwargs)


KDE_GLOBALS = Path.home() / ".config" / "kdeglobals"


def kde_window_lightness():
    """Lightness (0–255) of KDE's window background from ~/.config/kdeglobals,
    or None. Qt 6 programs don't always get KDE's palette on Plasma 5."""
    try:
        section = None
        for line in KDE_GLOBALS.read_text(encoding="utf-8", errors="replace").splitlines():
            line = line.strip()
            if line.startswith("["):
                section = line
            elif section == "[Colors:Window]" and line.startswith("BackgroundNormal="):
                r, g, b = (int(x) for x in line.split("=", 1)[1].split(",")[:3])
                return (max(r, g, b) + min(r, g, b)) / 2
    except (OSError, ValueError):
        pass
    return None


def system_is_dark():
    lightness = kde_window_lightness()
    if lightness is not None:
        return lightness < 128
    app = QApplication.instance()
    if app is None:
        return True
    try:
        return app.palette().color(app.palette().ColorRole.Window).lightness() < 128
    except Exception:
        return True


def _recolour(value, old):
    """A QColor/QBrush from the old theme, in the current one (None if unknown)."""
    if isinstance(value, QBrush):
        value = value.color()
    if not isinstance(value, QColor) or not value.isValid():
        return None
    key = old.reverse.get(value.name().lower())
    return tc(key) if key else None


def apply_theme(theme):
    """Switch to `theme` and re-apply it to every open window."""
    global THEME
    old, THEME = THEME, theme
    app = QApplication.instance()
    if app is None:
        return
    QApplication.setOverrideCursor(Qt.CursorShape.WaitCursor)
    try:
        for w in app.allWidgets():
            css = w.property("themeCss")
            if css is not None:
                w.setStyleSheet(th(css))
            html = w.property("themeHtml")
            if html is not None and hasattr(w, "setText"):
                w.setText(thtml(html))
            if isinstance(w, QTableWidget):
                for r in range(w.rowCount()):
                    for c in range(w.columnCount()):
                        item = w.item(r, c)
                        if item is not None:
                            for role in (Qt.ItemDataRole.ForegroundRole,
                                         Qt.ItemDataRole.BackgroundRole):
                                new = _recolour(item.data(role), old)
                                if new is not None:
                                    item.setData(role, new)
            elif isinstance(w, QTreeWidget):
                stack = [w.topLevelItem(i) for i in range(w.topLevelItemCount())]
                while stack:
                    item = stack.pop()
                    if item is None:
                        continue
                    for c in range(w.columnCount()):
                        for role in (Qt.ItemDataRole.ForegroundRole,
                                     Qt.ItemDataRole.BackgroundRole):
                            new = _recolour(item.data(c, role), old)
                            if new is not None:
                                item.setData(c, role, new)
                    stack.extend(item.child(i) for i in range(item.childCount()))
            elif isinstance(w, QTextEdit) and w.isReadOnly():
                html = w.toHtml()
                if "#" in html:
                    def swap(m):
                        key = old.reverse.get(m.group().lower())
                        return THEME.colour(key) if key else m.group()
                    bar = w.verticalScrollBar()
                    at_end = bar.value() >= bar.maximum() - 4
                    pos = bar.value()
                    w.setHtml(HEX_RE.sub(swap, html))
                    bar.setValue(bar.maximum() if at_end else pos)
            if isinstance(w, ResponsiveInfo):
                w.rescale()
            w.update()
    finally:
        QApplication.restoreOverrideCursor()



DATA_DIR = Path.home() / "SDS100Monitor"
