HEADERS = ["Start", "End", "Duration (s)", "System", "Department",
           "Channel", "Frequency", "Talkgroup", "RSSI (dBm)"]

def copy_text(text):
    QApplication.clipboard().setText(str(text))


def export_csv_rows(parent, rows, suggested="reception_selection.csv"):
    if not rows:
        return
    path, _ = QFileDialog.getSaveFileName(parent, "Export reception CSV", str(Path.home() / suggested), "CSV files (*.csv)")
    if path:
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(HEADERS)
                writer.writerows(rows)
        except OSError as exc:
            QMessageBox.warning(parent, "CSV export failed", str(exc))


def show_reception_details(parent, row, search_callback=None):
    dialog = QDialog(parent)
    dialog.setWindowTitle("Reception Details")
    dialog.resize(570, 390)
    layout = QVBoxLayout(dialog)
    details = QTextEdit()
    details.setReadOnly(True)
    details.setPlainText("\n".join(f"{key}: {value}" for key, value in zip(HEADERS, row)))
    layout.addWidget(details)
    buttons = QHBoxLayout()
    copy_btn = QPushButton("Copy Details")
    copy_btn.clicked.connect(lambda: copy_text(details.toPlainText()))
    buttons.addWidget(copy_btn)
    if search_callback and row[5]:
        similar = QPushButton("Find Similar Receptions")
        similar.clicked.connect(lambda: (search_callback(row[5]), dialog.accept()))
        buttons.addWidget(similar)
    close = QPushButton("Close")
    close.clicked.connect(dialog.accept)
    buttons.addWidget(close)
    layout.addLayout(buttons)
    dialog.exec()


def selected_record(table, point):
    item = table.itemAt(point)
    if item is None:
        return None
    row = item.row()
    return [table.item(row, c).text() if table.item(row, c) else "" for c in range(table.columnCount())]


# ---- Edit in Manager (v1.1.52; in both editions since 1.1.76) ---------------------------------
#
# Right-click a reception (or Tools → Edit Current Channel in Manager…) to open SDS100 Database &
# Favorites Manager's list editor on that talkgroup or channel. The request goes to a running
# Manager over a local socket on this computer (named per user); otherwise the newest installed
# Manager is started with --open-entry. Only names and IDs are sent; nothing is written here.

MANAGER_SERVER = f"sds100-database-favorites-manager-{os.getuid()}"


def manager_request(values):
    """What the Manager needs to find an entry, from reception values (System, Department, …)."""
    def clean(key):
        value = str(values.get(key, "") or "").strip()
        return "" if value == "\u2014" else value
    return {"system": clean("System"), "department": clean("Department"), "channel": clean("Channel"),
            "frequency": clean("Frequency"), "tgid": plain_id(clean("Talkgroup"), ("TGID",))}


def add_request(values):
    """Ask SDS-Manager to add what was heard to a Favorites List (1.1.73). Modulation when known."""
    request = manager_request(values)
    request["action"] = "add"
    modulation = str(values.get("Modulation", "") or "").strip().upper()
    request["modulation"] = modulation if modulation in ("FM", "NFM", "AM") else "AUTO"
    return request


def manager_version_key(name):
    m = re.search(r"(\d+)\.(\d+)\.(\d+)([a-z]?)", name)
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)) if m else (0, 0, 0, "")


def newest_manager_launcher(home=None):
    """launch.sh of the newest installed Manager (~/SDS100DatabaseFavoritesManager-<version>), or None."""
    if home is None:
        for command in ("/usr/bin/sds-manager", "/usr/bin/sds100-manager"):
            if Path(command).is_file():
                return Path(command)                # SDS-Manager's .deb (0.1.0 and later), or the older name
    home = Path(home or Path.home())
    if sys.platform == "darwin":
        for mac in (home / "SDS-Manager" / "launch-mac.sh", home / "Projects" / "SDS-Manager" / "launch-mac.sh"):
            if mac.is_file():
                return mac
    installs = [p for p in home.glob("SDS100DatabaseFavoritesManager-*")
                if p.is_dir() and not p.is_symlink() and (p / "launch.sh").is_file()]
    if not installs:
        return None
    return max(installs, key=lambda p: manager_version_key(p.name)) / "launch.sh"


def edit_in_manager(request, parent=None):
    """Send the request to the Manager (starting it if needed). Returns a status line."""
    if not (request.get("tgid") or request.get("frequency")):
        return ("Nothing to add: this reception has no talkgroup or frequency." if request.get("action") == "add"
                else "Nothing to look up: this reception has no talkgroup or frequency.")
    from PyQt6.QtNetwork import QLocalSocket
    socket = QLocalSocket()
    socket.connectToServer(MANAGER_SERVER)
    if socket.waitForConnected(500):
        socket.write((json.dumps(request) + "\n").encode("utf-8"))
        socket.flush()
        socket.waitForBytesWritten(1000)
        socket.waitForReadyRead(1500)
        socket.disconnectFromServer()
        return "Sent to SDS-Manager."
    launcher = newest_manager_launcher()
    if launcher is None:
        QMessageBox.information(parent, "Edit in Manager",
                                "SDS-Manager isn't installed (its package, sds-manager or "
                                "sds-manager-personal).")
        return "Manager not installed."
    try:
        subprocess.Popen(["/bin/bash", str(launcher), "--open-entry", json.dumps(request)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True)
    except OSError as exc:
        QMessageBox.warning(parent, "Edit in Manager", f"Couldn't start the Manager: {exc}")
        return "Manager not started."
    where = "installed package" if str(launcher).startswith("/usr/") else launcher.parent.name
    return f"Starting the Manager ({where})…"


def add_copy_actions(menu, row):
    for title, idx in (("Copy Channel Name", 5), ("Copy System Name", 3),
                       ("Copy Department", 4), ("Copy Frequency", 6),
                       ("Copy Talkgroup", 7)):
        menu.addAction(title, lambda checked=False, v=row[idx]: copy_text(v))
    menu.addAction("Copy Entire Record", lambda: copy_text("\t".join(row)))
    if len(row) >= len(HEADERS):
        menu.addSeparator()
        menu.addAction("Edit in Manager…", lambda: edit_in_manager(manager_request(dict(zip(HEADERS, row)))))
        menu.addAction("Add to Favorites List in Manager…",
                       lambda: edit_in_manager(add_request(dict(zip(HEADERS, row)))))


class HistoryArchiveBrowser(QDialog):
    """Read-only browser for complete daily CSV archives and legacy history."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Reception History Archive Browser")
        self.resize(1050, 660)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        self.current_rows = []
        self.filtered_rows = []
        self.page = 0
        self.page_size = 250
        layout = QVBoxLayout(self)
        row = QHBoxLayout()
        row.addWidget(make_label("Archive:"))
        self.files = QComboBox()
        self.files.setMinimumWidth(260)
        row.addWidget(self.files, 1)
        reload_btn = QPushButton("Refresh files")
        reload_btn.clicked.connect(self.refresh_files)
        row.addWidget(reload_btn)
        layout.addLayout(row)
        search_row = QHBoxLayout()
        search_row.addWidget(make_label("Search entire selected file:"))
        self.search = QLineEdit()
        self.search.setPlaceholderText("Channel, system, department, date, frequency, talkgroup…")
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(self.apply_filter)
        search_row.addWidget(self.search, 1)
        layout.addLayout(search_row)
        self.info = make_label("")
        layout.addWidget(self.info)
        self.table = QTableWidget(0, len(HEADERS))
        self.table.setHorizontalHeaderLabels(HEADERS)
        self.table.setAlternatingRowColors(True)
        self.table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Interactive)
        self.table.horizontalHeader().setStretchLastSection(True)
        self.table.setColumnWidth(0, 160)
        self.table.setColumnWidth(1, 160)
        self.table.setColumnWidth(5, 220)
        layout.addWidget(self.table, 1)
        pager = QHBoxLayout()
        self.prev_btn = QPushButton("◀ Previous")
        self.prev_btn.clicked.connect(lambda: self.show_page(self.page - 1))
        pager.addWidget(self.prev_btn)
        self.page_label = make_label("")
        pager.addWidget(self.page_label)
        self.next_btn = QPushButton("Next ▶")
        self.next_btn.clicked.connect(lambda: self.show_page(self.page + 1))
        pager.addWidget(self.next_btn)
        pager.addStretch()
        export_btn = QPushButton("Export matching rows…")
        export_btn.clicked.connect(self.export_matches)
        pager.addWidget(export_btn)
        layout.addLayout(pager)
        self.table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.table.customContextMenuRequested.connect(self.archive_context_menu)
        self.table.cellDoubleClicked.connect(self.archive_details)
        self.files.currentIndexChanged.connect(self.load_selected)
        self.refresh_files()

    def archive_details(self, row_index, _column):
        row = [self.table.item(row_index, c).text() if self.table.item(row_index, c) else ""
               for c in range(len(HEADERS))]
        show_reception_details(self, row, self.search.setText)

    def archive_context_menu(self, point):
        row = selected_record(self.table, point)
        menu = QMenu(self)
        if row:
            clicked = self.table.itemAt(point)
            menu.addAction("Copy Selected Cell", lambda: copy_text(clicked.text()))
            add_copy_actions(menu, row)
            menu.addSeparator()
            menu.addAction("View Reception Details…", lambda: show_reception_details(self, row, self.search.setText))
            menu.addAction("Find All Receptions on This Channel", lambda: set_text(self.search, row[5]))
            menu.addAction("Find All Receptions on This System", lambda: set_text(self.search, row[3]))
            menu.addAction("Export Selected Record…", lambda: export_csv_rows(self, [row]))
        menu.addSeparator()
        menu.addAction("Clear Search", self.search.clear).setEnabled(bool(self.search.text()))
        menu.addAction("Export Matching Records…", self.export_matches).setEnabled(bool(self.filtered_rows))
        menu.addSeparator()
        path = self.files.currentData()
        menu.addAction("Open CSV File", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(path))).setEnabled(bool(path))
        menu.addAction("Open History Folder", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(str(DAILY_LOG_DIR))))
        menu.exec(self.table.viewport().mapToGlobal(point))

    def refresh_files(self):
        previous = self.files.currentData()
        self.files.blockSignals(True)
        self.files.clear()
        for path in sorted(DAILY_LOG_DIR.glob("reception_history_????-??-??.csv"), reverse=True):
            if path.is_file() and not path.is_symlink():
                self.files.addItem(path.stem.replace("reception_history_", ""), str(path))
        if LEGACY_LOG_FILE.is_file() and not LEGACY_LOG_FILE.is_symlink():
            self.files.addItem("Legacy reception history", str(LEGACY_LOG_FILE))
        if previous:
            idx = self.files.findData(previous)
            if idx >= 0:
                self.files.setCurrentIndex(idx)
        self.files.blockSignals(False)
        self.load_selected()

    def load_selected(self, _index=None):
        self.current_rows = []
        path = self.files.currentData()
        if path:
            try:
                with open(path, newline="", encoding="utf-8-sig") as f:
                    reader = csv.reader(f)
                    header = next(reader, None)
                    if header != HEADERS:
                        QMessageBox.warning(self, "Unrecognized CSV", "Unexpected columns in archive:\n" + str(path))
                    else:
                        self.current_rows = [row for row in reader if len(row) == len(HEADERS)]
            except (OSError, csv.Error, UnicodeDecodeError) as exc:
                QMessageBox.warning(self, "Cannot open archive", f"{path}\n\n{exc}")
        self.apply_filter()

    def apply_filter(self, _text=None):
        term = self.search.text().strip().casefold()
        self.filtered_rows = [r for r in self.current_rows
                              if not term or any(term in cell.casefold() for cell in r)]
        self.page = 0
        self.show_page(0)

    def show_page(self, number):
        total = len(self.filtered_rows)
        pages = max(1, (total + self.page_size - 1) // self.page_size)
        self.page = max(0, min(number, pages - 1))
        start = self.page * self.page_size
        rows = self.filtered_rows[start:start + self.page_size]
        self.table.setSortingEnabled(False)
        self.table.setUpdatesEnabled(False)
        try:
            self.table.setRowCount(len(rows))
            for r, values in enumerate(rows):
                for c, value in enumerate(values):
                    self.table.setItem(r, c, QTableWidgetItem(value))
        finally:
            self.table.setUpdatesEnabled(True)
        set_text(self.info, f"{total:,} matching receptions / {len(self.current_rows):,} in selected archive")
        set_text(self.page_label, f"Page {self.page + 1} of {pages} (250 rows per page)")
        self.prev_btn.setEnabled(self.page > 0)
        self.next_btn.setEnabled(self.page + 1 < pages)
        self.table.verticalScrollBar().setValue(0)

    def export_matches(self):
        if not self.filtered_rows:
            QMessageBox.information(self, "No matching rows", "Nothing to export.")
            return
        suggested = str(Path.home() / "reception_history_filtered.csv")
        path, _ = QFileDialog.getSaveFileName(self, "Export matching receptions", suggested, "CSV files (*.csv)")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(HEADERS)
                writer.writerows(self.filtered_rows)
        except OSError as exc:
            QMessageBox.warning(self, "Export failed", str(exc))
            return
        QMessageBox.information(self, "Export complete", f"Exported {len(self.filtered_rows):,} rows.")



def port_users(port):
    """Other processes that have the serial port open (Linux /proc scan).

    Two programs reading the scanner at once split its replies between them
    and corrupt both, so the monitor refuses to connect in that case.
    """
    try:
        target = os.path.realpath(port)
        pids = [p for p in os.listdir("/proc") if p.isdigit()]
    except OSError:
        return []
    users = []
    for pid in pids:
        if int(pid) == os.getpid():
            continue
        try:
            for fd in os.listdir(f"/proc/{pid}/fd"):
                if os.path.realpath(f"/proc/{pid}/fd/{fd}") == target:
                    cmd = Path(f"/proc/{pid}/cmdline").read_bytes().replace(b"\0", b" ")
                    users.append(f"process {pid}: {cmd.decode(errors='replace').strip()[:120]}")
                    break
        except OSError:
            continue    # process ended, or belongs to another user
    return users


UNIDEN_USB_VID = 0x1965     # Uniden America


def monitor_settings():
    """The Monitor's settings. On macOS an INI file at the same path as on Linux
    (~/.config/SDS100Monitor/Monitor110.conf), so it follows $HOME the way Linux does."""
    if sys.platform != "darwin" or not hasattr(QSettings, "Format"):
        return QSettings("SDS100Monitor", "Monitor110")
    path = Path.home() / ".config" / "SDS100Monitor" / "Monitor110.conf"
    return QSettings(str(path), QSettings.Format.IniFormat)


def find_scanner_port(preferred):
    """Return the preferred port if present, otherwise a port that looks like
    a Uniden scanner (it can come back as /dev/ttyACM1 after a replug)."""
    try:
        ports = list(serial.tools.list_ports.comports())
    except Exception:
        return preferred
    if any(p.device == preferred for p in ports):
        return preferred
    for p in ports:
        text = " ".join(str(x or "") for x in (p.manufacturer, p.product, p.description)).lower()
        if getattr(p, "vid", None) == UNIDEN_USB_VID or "uniden" in text or "sds1" in text:
            return p.device
    return preferred


# Digital decode shown in the status bar (GSI Property P25Status, spec V2.00).
P25_STATUS_NAMES = {"Data": "data", "P25": "P25", "DMR": "DMR", "CAP": "Capacity Plus",
                    "CON": "Connect Plus", "DT3": "DMR Tier III", "XPT": "Hytera XPT",
                    "NX9": "NXDN 9600", "NX4": "NXDN 4800", "NXD": "NXDN"}


GRAPH_BINS = 240    # GWF FFT type 1: the 240 displayed FFT points


class ScannerThread(QThread):
    xml_received = pyqtSignal(str)
    message = pyqtSignal(str)
    command_result = pyqtSignal(str)
    graph_received = pyqtSignal(list)
    list_received = pyqtSignal(str)     # GLT XML block
    analyze_received = pyqtSignal(str)  # AST XML block (Analyze data)
    menu_received = pyqtSignal(str)     # MSI XML block (scanner menu)

    def __init__(self, port, baud, poll_ms):
        super().__init__()
        self.port, self.baud, self.poll_ms = port, baud, poll_ms
        self.running = True
        self.commands = queue.Queue()
        # Waterfall graph polling, switched on by the GUI while the scanner is
        # in waterfall mode. The scanner returns one GWF frame per request
        # (verified on an SDS100, 2026-10-26), so frames are polled.
        self.graph_enabled = False
        self.graph_ms = 250
        # Screen mirror polling (GST, or STS if GST is refused).
        self.screen_enabled = False
        self.screen_ms = 500
        self.screen_cmd = "GST"
        # Push updates (PSI, v1.1.42): the scanner sends its status report every
        # push_ms instead of being asked with GSI. 0 = poll with GSI as before.
        # If reports stop, PSI is sent again once (with KAL), then the thread
        # falls back to polling and says so.
        self.push_ms = 0
        self.last_status = 0.0

    def run(self):
        users = port_users(self.port)
        if users:
            self.message.emit(
                f"ERROR: {self.port} is already open in another program:\n"
                + "\n".join(users)
                + "\n\nClose it and connect again. Two programs reading the "
                  "scanner at once corrupt each other's data.")
            self.message.emit("DISCONNECTED")
            return
        try:
            # exclusive=True takes a lock so a second program using pyserial
            # (another SDS100 Monitor, the capture script) cannot open it too.
            with serial.Serial(self.port, self.baud, timeout=0.1,
                               write_timeout=1, exclusive=True) as device:
                self.message.emit("CONNECTED")
                time.sleep(0.35)
                device.reset_input_buffer()
                for cmd in (b"MDL\r", b"VER\r"):
                    device.write(cmd)
                device.flush()
                buf = b""
                last_poll = -1e9
                last_graph = -1e9
                last_screen = -1e9
                graph_on = False
                applied_push = 0
                push_retried = False
                retry_at = 0.0
                while self.running:
                    try:
                        cmd = self.commands.get_nowait()
                    except queue.Empty:
                        cmd = None
                    if cmd is not None:
                        device.write((cmd + "\r").encode("ascii"))
                        device.flush()
                        self.command_result.emit("SENT: " + cmd)
                    now = time.monotonic()
                    if self.push_ms != applied_push:
                        device.write(f"PSI,{self.push_ms}\r".encode("ascii"))
                        device.flush()
                        applied_push = self.push_ms
                        push_retried = False
                        self.last_status = now
                        self.message.emit(f"PUSH:{'ON' if applied_push else 'OFF'}")
                    if applied_push:
                        limit = max(2.5, applied_push * 4 / 1000)
                        if now - self.last_status > limit:
                            if not push_retried:
                                device.write(f"KAL\rPSI,{applied_push}\r".encode("ascii"))
                                device.flush()
                                push_retried = True
                                retry_at = self.last_status = now
                            else:
                                device.write(b"PSI,0\r")
                                device.flush()
                                self.push_ms = applied_push = 0
                                self.message.emit("PUSH:FALLBACK")
                        elif push_retried and self.last_status > retry_at:
                            push_retried = False     # reports came back after the retry
                    elif (now - last_poll) * 1000 >= self.poll_ms:
                        device.write(b"GSI\r")
                        device.flush()
                        last_poll = now
                    if self.graph_enabled:
                        if (now - last_graph) * 1000 >= self.graph_ms:
                            device.write(b"GWF,1,ON\r")
                            device.flush()
                            last_graph = now
                            graph_on = True
                    elif graph_on:
                        device.write(b"GWF,1,OFF\r")
                        device.flush()
                        graph_on = False
                    if self.screen_enabled and (now - last_screen) * 1000 >= self.screen_ms:
                        device.write((self.screen_cmd + "\r").encode("ascii"))
                        device.flush()
                        last_screen = now
                    data = device.read(4096)
                    if data:
                        buf += data
                    buf = self.consume(buf)
                if applied_push:
                    device.write(b"PSI,0\r")         # stop the scanner pushing
                # Send anything still queued (for example a key release)
                # before the port closes, instead of silently dropping it.
                while True:
                    try:
                        cmd = self.commands.get_nowait()
                    except queue.Empty:
                        break
                    device.write((cmd + "\r").encode("ascii"))
                    self.command_result.emit("SENT: " + cmd)
                device.flush()
        except (serial.SerialException, OSError) as exc:
            self.message.emit("ERROR: " + str(exc))
        finally:
            self.message.emit("DISCONNECTED")

    def consume(self, buf):
        """Split the serial buffer into plain-text replies and XML blocks.

        Data is handled strictly in arrival order, so a reply such as KEY,OK
        that arrives in the same read as a GSI response is no longer discarded.
        XML blocks: GSI status (<ScannerInfo>), GLT lists (<GLT>), Analyze
        data (<AST>) and the scanner menu (<MSI>). Returns the unconsumed
        remainder of the buffer.
        """
        blocks = (
            (b"<ScannerInfo", b"</ScannerInfo>", 131072, self.xml_received),
            (b"<GLT", b"</GLT>", 2_000_000, self.list_received),
            (b"<AST", b"</AST>", 1_000_000, self.analyze_received),
            (b"<MSI", b"</MSI>", 262144, self.menu_received),
        )
        while True:
            starts = [(i, block) for block in blocks
                      if (i := self.find_tag(buf, block[0])) >= 0]
            xml_start, block = min(starts, key=lambda s: s[0]) if starts else (-1, None)
            # Lines normally end in CR; GCS replies end in LF (spec V2.00).
            ends = [i for i in (buf.find(b"\r"), buf.find(b"\n")) if i >= 0]
            cr = min(ends) if ends else -1
            if xml_start >= 0 and (cr < 0 or xml_start < cr):
                prefix = buf[:xml_start]
                open_tag, close_tag, limit, signal = block
                gt = buf.find(b">", xml_start)
                if gt >= 0 and buf[gt - 1:gt] == b"/":
                    end = gt + 1                              # empty, e.g. <GLT/>
                else:
                    end = buf.find(close_tag, xml_start)
                    end = end + len(close_tag) if end >= 0 else -1
                if end < 0:
                    if len(buf) - xml_start > limit:
                        return b""
                    return buf
                self.emit_reply(prefix)
                if open_tag == b"<ScannerInfo":
                    # (Compared by tag: Qt returns a new bound-signal object on every
                    # attribute access, so "signal is self.xml_received" is never true.)
                    self.last_status = time.monotonic()
                signal.emit(buf[xml_start:end].decode("utf-8", "replace"))
                buf = buf[end:]
                continue
            if cr < 0:
                return buf[-1024:] if len(buf) > 8192 else buf
            line, buf = buf[:cr], buf[cr + 1:]
            self.emit_reply(line)

    @staticmethod
    def find_tag(buf, tag):
        """Position of an opening tag (followed by space, > or /), or -1."""
        start = 0
        while True:
            i = buf.find(tag, start)
            if i < 0:
                return -1
            after = buf[i + len(tag):i + len(tag) + 1]
            if after in (b" ", b">", b"/", b"\r", b"\n", b"\t") or after == b"":
                return i
            start = i + 1

    @staticmethod
    def parse_graph(response):
        """Return the 240 levels (0-255) of a GWF frame, or None.

        Verified format: GWF,<240 two-digit hex values, comma separated>,
        """
        parts = response[4:].strip().strip(",").split(",")
        if len(parts) != GRAPH_BINS:
            return None
        try:
            return [int(p, 16) for p in parts]
        except ValueError:
            return None

    def emit_reply(self, raw):
        response = raw.decode("utf-8", "replace").strip()
        if response.startswith("GWF,"):
            values = self.parse_graph(response)
            if values is not None:
                self.graph_received.emit(values)
                return
        if response.startswith("PSI,") and response.rstrip(",").endswith(("NG", "ERR")):
            if self.push_ms:
                self.push_ms = 0
                self.message.emit("PUSH:REFUSED")
            return
        # GSI/PSI framing lines are part of the XML response, not command replies.
        if response and not response.startswith(("GSI,", "PSI,", "GLT,<XML>", "AST,<XML>",
                                                  "MSI,<XML>", "<?xml")):
            # Pass the whole reply on: FQK/SQK/DQK replies carry 100 values
            # (about 200 characters). Only the on-screen text is shortened.
            self.command_result.emit("REPLY: " + response)

    def send_command(self, command):
        self.commands.put(command)

    def stop(self):
        self.running = False
        self.wait(2500)


class KeyProtocolDiagnostic(QDialog):
    """Manual, one-command-at-a-time KEY_MODE investigation tool."""
    def __init__(self, monitor):
        super().__init__(monitor)
        self.monitor = monitor
        self.setWindowTitle("SDS100 Keypress Protocol Diagnostic • experimental")
        self.resize(720, 550)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        layout = QVBoxLayout(self)
        note = make_label("Experimental remote key modes are NOT documented in SDS100 spec v1.02. "
                      "Test only while watching the scanner. P is established; L/H/R are hypotheses. "
                      "A KEY,OK reply confirms receipt, not that the expected function occurred.")
        note.setWordWrap(True)
        layout.addWidget(note)
        line = QHBoxLayout()
        line.addWidget(make_label("Key:"))
        self.key = QComboBox()
        for name, code in [("1","1"),("2","2"),("3","3"),("4 / ATT","4"),("5 / DIM","5"),
                           ("6 / WX","6"),("7 / IFX","7"),("8 / REV","8"),("9 / DISP","9"),
                           ("0 / LVL","0"),("FUNC","F"),("AVOID","L"),("REPLAY","Y"),
                           ("SYSTEM","A"),("DEPT","B"),("CHANNEL","C"),("MENU","M"),
                           ("E/YES","E"),("./NO","."),("BACKLIGHT","V"),("RANGE","R")]:
            self.key.addItem(name,code)
        self.key.setCurrentIndex(self.key.findData("6"))
        line.addWidget(self.key)
        line.addWidget(make_label("KEY_MODE:"))
        self.mode = QComboBox()
        for mode, name in [("P","P — normal press (known)"),("L","L — possible long press"),
                           ("H","H — possible hold"),("R","R — possible release")]:
            self.mode.addItem(name,mode)
        line.addWidget(self.mode)
        layout.addLayout(line)
        self.preview = QLabel()
        layout.addWidget(self.preview)
        self.key.currentIndexChanged.connect(self.update_preview)
        self.mode.currentIndexChanged.connect(self.update_preview)
        self.update_preview()
        self.ack = QCheckBox("I understand this is an undocumented command and will observe the scanner.")
        layout.addWidget(self.ack)
        self.send_btn = QPushButton("Send exactly this command")
        self.send_btn.clicked.connect(self.send_test)
        layout.addWidget(self.send_btn)
        self.release_btn = QPushButton("Release selected key (KEY,<key>,R) — experimental")
        self.release_btn.clicked.connect(self.release_key)
        layout.addWidget(self.release_btn)
        self.log = QTextEdit()
        self.log.setReadOnly(True)
        layout.addWidget(self.log,1)
        self.log.append("Only commands sent from this diagnostic window are logged below. "
                        "Incoming serial replies are shared with normal scanner polling; "
                        "they are not guaranteed to correspond to the preceding command.")
        # Subscribe through the main window, so the log keeps working after
        # a disconnect/reconnect creates a new serial thread.
        self.monitor.scanner_output.connect(self.log_reply)
        close = QPushButton("Close")
        close.clicked.connect(self.close)
        layout.addWidget(close)

    # The held key is stored on the main window, which outlives this dialog
    # and can release the key when the program closes or disconnects.
    @property
    def held_key(self):
        return self.monitor.diagnostic_held_key

    @held_key.setter
    def held_key(self, value):
        self.monitor.diagnostic_held_key = value

    def update_preview(self):
        set_text(self.preview, f"Exact command: KEY,{self.key.currentData()},{self.mode.currentData()}\r")

    def ready(self):
        if not self.monitor.thread or not self.monitor.thread.isRunning():
            QMessageBox.warning(self,"Disconnected","Connect the SDS100 before sending test commands.")
            return False
        if not self.ack.isChecked():
            QMessageBox.information(self,"Confirmation required","Check the experimental-command acknowledgement first.")
            return False
        return True

    def send_test(self):
        if not self.ready():
            return
        key,mode = self.key.currentData(),self.mode.currentData()
        if mode in ("H","L"):
            result = QMessageBox.question(self,"Confirm experimental key mode",
                f"Send KEY,{key},{mode}?\nThis may change scanner settings or leave a key held. "
                "The program cannot guarantee release if the connection drops.")
            if result != QMessageBox.StandardButton.Yes:
                return
        self.monitor.thread.send_command(f"KEY,{key},{mode}")
        self.log.append(f"QUEUED: KEY,{key},{mode}")
        if mode == "H":
            self.held_key = key
            set_text(self.release_btn, f"Release held key {key} (KEY,{key},R) — experimental")
        elif mode == "R" and self.held_key == key:
            self.held_key = None

    def release_key(self):
        if not self.ready():
            return
        key = self.held_key or self.key.currentData()
        self.monitor.thread.send_command(f"KEY,{key},R")
        self.log.append(f"QUEUED RELEASE: KEY,{key},R")
        self.held_key = None

    def log_reply(self, message):
        self.log.append(message)

    def closeEvent(self, event):
        key = self.monitor.release_diagnostic_key()
        if key:
            self.log.append(f"QUEUED AUTOMATIC RELEASE: KEY,{key},R")
        super().closeEvent(event)


# ---- Scanner Information panel: your choice of lines, colours and conditional colours (1.1.71) --------------
# Every field the panel can show, with its label. The first nine are the panel as it was before.
INFO_FIELDS = {
    "System": "System", "Site": "Site", "Department": "Department", "Channel": "Channel",
    "Frequency": "Frequency", "Talkgroup": "Talkgroup", "Unit ID": "Unit ID", "Mode": "Mode", "RSSI": "RSSI",
    "Favorites List": "Favorites List", "Favorites List Quick Key": "Favorites List quick key",
    "Favorites List Number Tag": "Favorites List number tag",
    "Service Type": "Service type", "Modulation": "Modulation", "System Type": "System type",
    "System Quick Key": "System quick key", "System Number Tag": "System number tag",
    "Department Quick Key": "Department quick key", "Site Quick Key": "Site quick key (department set)",
    "Channel Number Tag": "Channel number tag",
    "P25 Status": "P25 status (NAC / colour code / RAN)", "Hold": "Hold", "Avoid": "Avoid",
    "Attenuator": "Attenuator", "Recording": "Recording (scanner)", "Volume": "Volume", "Squelch": "Squelch",
    "Signal Bars": "Signal bars (scanner)", "Reception Start": "Reception started", "Duration": "Reception length",
    "Clock": "Clock", "Custom": "Custom text…",
}
DEFAULT_INFO_FIELDS = ("System", "Site", "Department", "Channel", "Frequency", "Talkgroup", "Unit ID", "Mode",
                       "RSSI")
INFO_OPS = ("contains", "is", "is not", "starts with", "is empty", "is not empty", "number ≥", "number ≤")
INFO_LAYOUT_FILE = DATA_DIR / "info_panel.json"
_HEX = re.compile(r"#[0-9a-fA-F]{6}")


def default_info_line(field):
    return {"field": field, "label": INFO_FIELDS.get(field, field).upper() if field != "Custom" else "",
            "show_label": True, "template": "{System} › {Department}" if field == "Custom" else "",
            "fg": "", "bg": "", "size": 100, "bold": False}


def default_info_layout():
    return {"lines": [default_info_line(f) for f in DEFAULT_INFO_FIELDS], "panel_bg": "", "rules": []}


def _colour(value):
    return value if isinstance(value, str) and _HEX.fullmatch(value) else ""


def clean_info_layout(data):
    """A layout with only known fields and sane values (anything odd falls back to the default)."""
    if not isinstance(data, dict) or not isinstance(data.get("lines"), list):
        return default_info_layout()
    lines = []
    for line in data["lines"]:
        if not isinstance(line, dict) or line.get("field") not in INFO_FIELDS:
            continue
        clean = default_info_line(line["field"])
        clean["label"] = str(line.get("label", clean["label"]))[:40]
        clean["show_label"] = bool(line.get("show_label", True))
        clean["template"] = str(line.get("template", clean["template"]))[:200]
        clean["fg"], clean["bg"] = _colour(line.get("fg")), _colour(line.get("bg"))
        try:
            clean["size"] = max(50, min(300, int(line.get("size", 100))))
        except (TypeError, ValueError):
            pass
        clean["bold"] = bool(line.get("bold", False))
        lines.append(clean)
    rules = []
    for rule in data.get("rules", []) if isinstance(data.get("rules"), list) else []:
        if isinstance(rule, dict) and rule.get("field") in INFO_FIELDS and rule.get("op") in INFO_OPS:
            rules.append({"field": rule["field"], "op": rule["op"], "value": str(rule.get("value", ""))[:100],
                          "target": "panel" if rule.get("target") == "panel" else "line",
                          "fg": _colour(rule.get("fg")), "bg": _colour(rule.get("bg"))})
    return {"lines": lines or default_info_layout()["lines"], "panel_bg": _colour(data.get("panel_bg")),
            "rules": rules}


def load_info_settings(path=None):
    """{'current': layout, 'presets': {name: layout}} from the saved file (defaults if none)."""
    try:
        data = json.loads(Path(path or INFO_LAYOUT_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        data = {}
    presets = data.get("presets") if isinstance(data, dict) and isinstance(data.get("presets"), dict) else {}
    return {"current": clean_info_layout(data.get("current")) if isinstance(data, dict) else default_info_layout(),
            "presets": {str(k)[:40]: clean_info_layout(v) for k, v in presets.items()}}


def save_info_settings(settings, path=None):
    path = Path(path or INFO_LAYOUT_FILE)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(".tmp")
    temporary.write_text(json.dumps(settings, indent=1), encoding="utf-8")
    os.replace(temporary, path)


def info_text(line, values):
    """What a line shows: its field's value, or a Custom line's template filled in ({System} etc.)."""
    if line["field"] != "Custom":
        return values.get(line["field"], "—") or "—"
    def fill(match):
        return values.get(match.group(1), match.group(0)) or "—"
    return re.sub(r"\{([A-Za-z0-9 ]+)\}", fill, line.get("template", "")) or "—"


def rule_matches(rule, values):
    value = str(values.get(rule["field"], "") or "").strip()
    empty = value in ("", "—", "None")
    wanted = rule.get("value", "").strip()
    op = rule["op"]
    if op == "is empty":
        return empty
    if op == "is not empty":
        return not empty
    if empty:
        return False
    low, want = value.casefold(), wanted.casefold()
    if op == "contains":
        return bool(want) and want in low
    if op == "is":
        return low == want
    if op == "is not":
        return low != want
    if op == "starts with":
        return bool(want) and low.startswith(want)
    match = re.search(r"-?\d+(?:\.\d+)?", value)
    try:
        number, limit = float(match.group(0)) if match else None, float(wanted)
    except ValueError:
        return False
    if number is None:
        return False
    return number >= limit if op == "number ≥" else number <= limit


def info_styles(layout, values):
    """(panel background, [(fg, bg) per line]) after the conditional colours: later rules win."""
    panel = layout.get("panel_bg", "")
    styles = [[line["fg"], line["bg"]] for line in layout["lines"]]
    for rule in layout.get("rules", []):
        if not rule_matches(rule, values):
            continue
        if rule["target"] == "panel":
            panel = rule["bg"] or panel
            for style in styles:
                style[0] = rule["fg"] or style[0]
        else:
            for line, style in zip(layout["lines"], styles):
                if line["field"] == rule["field"] or (line["field"] == "Custom"
                                                      and "{" + rule["field"] + "}" in line["template"]):
                    style[0] = rule["fg"] or style[0]
                    style[1] = rule["bg"] or style[1]
    return panel, [tuple(s) for s in styles]


def info_line_css(fg, bg, bold):
    parts = []
    if fg:
        parts.append(f"color:{fg};")
    if bg:
        parts.append(f"background:{bg}; border-radius:4px; padding:1px 6px;")
    if bold:
        parts.append("font-weight:bold;")
    return " ".join(parts)


def gsi_extras(root, system, department, channel, prop):
    """The extra fields the scanner reports in a status update (GSI)."""
    def attr(node, name):
        value = node.attrib.get(name, "") if node is not None else ""
        return value if value not in ("", "None") else "—"
    site = root.find("Site") if root is not None else None       # trunked site (1.1.78)
    hold = next((attr(n, "Hold") for n in (channel, department, site, system) if attr(n, "Hold") == "On"), "—")
    if hold == "—" and any(attr(n, "Hold") == "Off" for n in (channel, department, site, system)):
        hold = "Off"
    monitored = root.find("MonitorList") if root is not None else None
    list_type = attr(monitored, "ListType")
    list_name = attr(monitored, "Name")
    if list_type == "FullDb" and list_name == "—":
        list_name = "Full Database"
    return {
        # 1.1.72: the list the scanner is playing from (Favorites List, Full Database or a search list).
        "Favorites List": list_name, "Favorites List Quick Key": attr(monitored, "Q_Key"),
        "Favorites List Number Tag": attr(monitored, "N_Tag"),
        "Service Type": attr(channel, "SvcType"), "Modulation": attr(channel, "Mod"),
        "System Type": attr(system, "SystemType"), "System Quick Key": attr(system, "Q_Key"),
        "System Number Tag": attr(system, "N_Tag"), "Department Quick Key": attr(department, "Q_Key"),
        "Site Quick Key": attr(site, "Q_Key"),
        "Channel Number Tag": attr(channel, "N_Tag"), "P25 Status": attr(prop, "P25Status"),
        "Hold": hold, "Avoid": attr(channel, "Avoid"), "Attenuator": attr(prop, "Att"),
        "Recording": attr(prop, "Rec"), "Volume": attr(prop, "VOL"), "Squelch": attr(prop, "SQL"),
        "Signal Bars": attr(prop, "Sig"),
    }


class InfoPanelDialog(QDialog):
    """View → Customize Scanner Information…: lines, colours, conditional colours and presets."""

    def __init__(self, parent, settings, apply):
        super().__init__(parent)
        self.setWindowTitle("Customize Scanner Information")
        self.resize(980, 640)
        if not isinstance(settings, dict) or "current" not in settings:
            settings = load_info_settings()
        if not callable(apply):
            apply = lambda _layout: None
        self.settings = json.loads(json.dumps(settings))
        self.original = json.loads(json.dumps(settings["current"]))
        self.layout_data = json.loads(json.dumps(settings["current"]))
        self.apply_live = apply
        self._loading = False
        outer = QVBoxLayout(self)
        tabs = QTabWidget()
        outer.addWidget(tabs, 1)
        # -- lines --
        lines_page = QWidget()
        row = QHBoxLayout(lines_page)
        left = QVBoxLayout()
        self.line_list = QListWidget()
        self.line_list.currentRowChanged.connect(self.show_line)
        left.addWidget(self.line_list, 1)
        adder = QHBoxLayout()
        self.add_choice = QComboBox()
        for key, label in INFO_FIELDS.items():
            self.add_choice.addItem(label, key)
        adder.addWidget(self.add_choice, 1)
        add = QPushButton("Add Line")
        add.clicked.connect(self.add_line)
        adder.addWidget(add)
        left.addLayout(adder)
        moves = QHBoxLayout()
        for text, slot in (("Up", lambda: self.move_line(-1)), ("Down", lambda: self.move_line(1)),
                           ("Remove", self.remove_line)):
            b = QPushButton(text)
            b.clicked.connect(slot)
            moves.addWidget(b)
        left.addLayout(moves)
        row.addLayout(left, 1)
        form_box = QGroupBox("Selected line")
        form = QFormLayout(form_box)
        self.label_edit = QLineEdit()
        self.label_edit.textEdited.connect(lambda t: self.set_line("label", t))
        form.addRow("Label", self.label_edit)
        self.show_label = QCheckBox("Show the label")
        self.show_label.toggled.connect(lambda on: self.set_line("show_label", on))
        form.addRow("", self.show_label)
        self.template_edit = QLineEdit()
        self.template_edit.setToolTip("Field names in braces, for example {System} › {Department} — {Talkgroup}")
        self.template_edit.textEdited.connect(lambda t: self.set_line("template", t))
        form.addRow("Custom text", self.template_edit)
        self.fg_button = QPushButton("Text colour…")
        self.fg_button.clicked.connect(lambda: self.pick_line_colour("fg"))
        self.bg_button = QPushButton("Background…")
        self.bg_button.clicked.connect(lambda: self.pick_line_colour("bg"))
        colours = QHBoxLayout()
        colours.addWidget(self.fg_button)
        colours.addWidget(self.bg_button)
        clear = QPushButton("Theme colours")
        clear.setToolTip("Use the theme's colours for this line")
        clear.clicked.connect(self.clear_line_colours)
        colours.addWidget(clear)
        form.addRow("Colours", colours)
        self.size_spin = QSpinBox()
        self.size_spin.setRange(50, 300)
        self.size_spin.setSuffix(" %")
        self.size_spin.valueChanged.connect(lambda v: self.set_line("size", v))
        form.addRow("Size", self.size_spin)
        self.bold = QCheckBox("Bold")
        self.bold.toggled.connect(lambda on: self.set_line("bold", on))
        form.addRow("", self.bold)
        self.panel_bg = QPushButton("Panel background…")
        self.panel_bg.clicked.connect(self.pick_panel_colour)
        panel_clear = QPushButton("Theme background")
        panel_clear.clicked.connect(lambda: self.set_panel(""))
        panel_row = QHBoxLayout()
        panel_row.addWidget(self.panel_bg)
        panel_row.addWidget(panel_clear)
        form.addRow("Whole panel", panel_row)
        row.addWidget(form_box, 1)
        tabs.addTab(lines_page, "Lines")
        # -- conditional colours --
        rules_page = QWidget()
        rules_layout = QVBoxLayout(rules_page)
        rules_layout.addWidget(make_label(
            "Colour a line, or the whole panel, when a field matches. Rules are checked top to bottom; later "
            "ones win. Example: Service Type contains Fire → this line red."))
        self.rule_table = QTableWidget(0, 6)
        self.rule_table.setHorizontalHeaderLabels(["When", "Condition", "Value", "Colour", "Text", "Background"])
        self.rule_table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        rules_layout.addWidget(self.rule_table, 1)
        rule_buttons = QHBoxLayout()
        for text, slot in (("Add Rule", self.add_rule), ("Remove Rule", self.remove_rule)):
            b = QPushButton(text)
            b.clicked.connect(slot)
            rule_buttons.addWidget(b)
        rule_buttons.addStretch(1)
        rules_layout.addLayout(rule_buttons)
        tabs.addTab(rules_page, "Conditional Colours")
        # -- presets --
        bottom = QHBoxLayout()
        bottom.addWidget(make_label("Preset:"))
        self.preset_choice = QComboBox()
        self.preset_choice.setMinimumWidth(180)
        bottom.addWidget(self.preset_choice)
        for text, slot in (("Load", self.load_preset), ("Save as Preset…", self.save_preset),
                           ("Delete", self.delete_preset), ("Default Layout", self.reset_default)):
            b = QPushButton(text)
            b.clicked.connect(slot)
            bottom.addWidget(b)
        bottom.addStretch(1)
        outer.addLayout(bottom)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Apply
                                   | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        buttons.button(QDialogButtonBox.StandardButton.Apply).clicked.connect(self.preview)
        outer.addWidget(buttons)
        self.fill_presets()
        self.fill_lines()
        self.fill_rules()

    # ---- lines --------------------------------------------------------------------------------
    def fill_lines(self, select=0):
        self.line_list.clear()
        for line in self.layout_data["lines"]:
            name = INFO_FIELDS.get(line["field"], line["field"])
            if line["field"] == "Custom":
                name = f"Custom: {line['template']}"
            self.line_list.addItem(name)
        if self.layout_data["lines"]:
            self.line_list.setCurrentRow(max(0, min(select, len(self.layout_data["lines"]) - 1)))

    def current_line(self):
        index = self.line_list.currentRow()
        return self.layout_data["lines"][index] if 0 <= index < len(self.layout_data["lines"]) else None

    def show_line(self, _index):
        line = self.current_line()
        if line is None:
            return
        self._loading = True
        try:
            self.label_edit.setText(line["label"])
            self.show_label.setChecked(line["show_label"])
            self.template_edit.setText(line["template"])
            self.template_edit.setEnabled(line["field"] == "Custom")
            self.size_spin.setValue(line["size"])
            self.bold.setChecked(line["bold"])
            self.fg_button.setStyleSheet(f"color:{line['fg']};" if line["fg"] else "")
            self.bg_button.setStyleSheet(f"background:{line['bg']};" if line["bg"] else "")
        finally:
            self._loading = False

    def set_line(self, key, value):
        line = self.current_line()
        if line is None or self._loading:
            return
        line[key] = value
        if key == "template":
            self.line_list.currentItem().setText(f"Custom: {value}")

    def add_line(self):
        self.layout_data["lines"].append(default_info_line(self.add_choice.currentData()))
        self.fill_lines(len(self.layout_data["lines"]) - 1)

    def remove_line(self):
        index = self.line_list.currentRow()
        if 0 <= index < len(self.layout_data["lines"]) and len(self.layout_data["lines"]) > 1:
            del self.layout_data["lines"][index]
            self.fill_lines(index)

    def move_line(self, step):
        index = self.line_list.currentRow()
        target = index + step
        lines = self.layout_data["lines"]
        if 0 <= index < len(lines) and 0 <= target < len(lines):
            lines[index], lines[target] = lines[target], lines[index]
            self.fill_lines(target)

    def pick_colour(self, start):
        from PyQt6.QtWidgets import QColorDialog
        from PyQt6.QtGui import QColor
        colour = QColorDialog.getColor(QColor(start) if start else QColor("#ffffff"), self, "Choose a colour")
        return colour.name() if colour.isValid() else None

    def pick_line_colour(self, key):
        line = self.current_line()
        if line is None:
            return
        colour = self.pick_colour(line[key])
        if colour:
            line[key] = colour
            self.show_line(self.line_list.currentRow())

    def clear_line_colours(self):
        line = self.current_line()
        if line is not None:
            line["fg"] = line["bg"] = ""
            self.show_line(self.line_list.currentRow())

    def pick_panel_colour(self):
        colour = self.pick_colour(self.layout_data.get("panel_bg", ""))
        if colour:
            self.set_panel(colour)

    def set_panel(self, colour):
        self.layout_data["panel_bg"] = colour
        self.panel_bg.setStyleSheet(f"background:{colour};" if colour else "")

    # ---- rules -------------------------------------------------------------------------------------
    def fill_rules(self):
        self.rule_table.setRowCount(0)
        for rule in self.layout_data["rules"]:
            self.add_rule(rule)

    def add_rule(self, rule=None):
        rule = rule if isinstance(rule, dict) else {"field": "Service Type", "op": "contains", "value": "Fire",
                                                    "target": "line", "fg": "#ffffff", "bg": "#b3261e"}
        r = self.rule_table.rowCount()
        self.rule_table.insertRow(r)
        field = QComboBox()
        for key, label in INFO_FIELDS.items():
            if key != "Custom":
                field.addItem(label, key)
        field.setCurrentIndex(max(0, field.findData(rule["field"])))
        op = QComboBox()
        op.addItems(INFO_OPS)
        op.setCurrentText(rule["op"])
        value = QLineEdit(rule.get("value", ""))
        target = QComboBox()
        target.addItem("That line", "line")
        target.addItem("Whole panel", "panel")
        target.setCurrentIndex(1 if rule.get("target") == "panel" else 0)
        self.rule_table.setCellWidget(r, 0, field)
        self.rule_table.setCellWidget(r, 1, op)
        self.rule_table.setCellWidget(r, 2, value)
        self.rule_table.setCellWidget(r, 3, target)
        for column, key in ((4, "fg"), (5, "bg")):
            button = QPushButton(rule.get(key) or "Theme")
            button.setProperty("colour", rule.get(key, ""))
            button.setStyleSheet(f"background:{rule[key]};" if rule.get(key) else "")
            button.clicked.connect(lambda _c=False, b=button: self.pick_rule_colour(b))
            self.rule_table.setCellWidget(r, column, button)

    def pick_rule_colour(self, button):
        colour = self.pick_colour(button.property("colour") or "")
        if colour:
            button.setProperty("colour", colour)
            button.setText(colour)
            button.setStyleSheet(f"background:{colour};")

    def remove_rule(self):
        r = self.rule_table.currentRow()
        if r < 0:
            r = self.rule_table.rowCount() - 1
        if r >= 0:
            self.rule_table.removeRow(r)

    def read_rules(self):
        rules = []
        for r in range(self.rule_table.rowCount()):
            cells = [self.rule_table.cellWidget(r, c) for c in range(6)]
            rules.append({"field": cells[0].currentData(), "op": cells[1].currentText(), "value": cells[2].text(),
                          "target": cells[3].currentData(), "fg": cells[4].property("colour") or "",
                          "bg": cells[5].property("colour") or ""})
        return rules

    # ---- presets and results -----------------------------------------------------------------------
    def fill_presets(self):
        self.preset_choice.clear()
        self.preset_choice.addItems(sorted(self.settings["presets"], key=str.casefold))

    def result_layout(self):
        data = dict(self.layout_data, rules=self.read_rules())
        return clean_info_layout(data)

    def save_preset(self):
        name, ok = QInputDialog.getText(self, "Save Preset", "Preset name (for example Large print, Night):",
                                        text=self.preset_choice.currentText())
        name = name.strip()[:40]
        if ok and name:
            self.settings["presets"][name] = self.result_layout()
            self.fill_presets()
            self.preset_choice.setCurrentText(name)

    def load_preset(self):
        layout = self.settings["presets"].get(self.preset_choice.currentText())
        if layout:
            self.layout_data = json.loads(json.dumps(layout))
            self.fill_lines()
            self.fill_rules()
            self.set_panel(self.layout_data.get("panel_bg", ""))

    def delete_preset(self):
        self.settings["presets"].pop(self.preset_choice.currentText(), None)
        self.fill_presets()

    def reset_default(self):
        self.layout_data = default_info_layout()
        self.fill_lines()
        self.fill_rules()
        self.set_panel("")

    def preview(self):
        self.apply_live(self.result_layout())

    def result_settings(self):
        return {"current": self.result_layout(), "presets": self.settings["presets"]}


class ResponsiveInfo(QWidget):
    """Scale information text to the available dock width and height."""
    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.rescale()

    def rescale(self):
        scale = min(self.width() / 560, self.height() / 420) * THEME.scale
        size = max(round(10 * THEME.scale), min(round(24 * THEME.scale), round(15 * scale)))
        for label in self.findChildren(QLabel):
            if label.objectName() == "value":
                font = label.font()
                percent = label.property("size_pct") or 100      # per-line size (1.1.71)
                font.setPointSize(max(6, round(size * percent / 100)))
                font.setBold(bool(label.property("bold")))
                label.setFont(font)


def parse_mhz(text):
    """' 162.550000MHz' -> 162.55; returns None if not a frequency."""
    try:
        return float(str(text).strip().lower().removesuffix("mhz").strip())
    except ValueError:
        return None


def parse_step_mhz(text):
    """'25kHz' -> 0.025, '6.25kHz' -> 0.00625; 'Auto' or unknown -> None."""
    t = str(text).strip().lower()
    try:
        if t.endswith("khz"):
            return float(t[:-3]) / 1000
        if t.endswith("mhz"):
            return float(t[:-3])
    except ValueError:
        pass
    return None


class WaterfallGraph(QWidget):
    """Live FFT trace (top) and scrolling waterfall (bottom) from GWF frames.

    Bin i of the 240 is drawn at Lower + i x (Upper - Lower) / 240, which puts
    the center frequency at bin 120, as seen in SDS100 captures.
    """
    tune_requested = pyqtSignal(float)
    HISTORY = 200        # waterfall rows kept
    AXIS = 20            # pixels for the frequency labels

    def __init__(self):
        super().__init__()
        self.setMinimumHeight(300)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setMouseTracking(True)
        self.setToolTip("Double-click to move the scanner's marker to that frequency")
        self.lower = self.upper = self.marker = self.step = None
        self.current = None
        self.floor = None
        self.rows = bytearray(GRAPH_BINS * 4 * self.HISTORY)
        self.row_count = 0
        self.message = "Waterfall not active"
        self.lut_night = None
        self.build_lut()

    def build_lut(self):
        """Colour scale: black → blue → cyan → yellow → red → white; in Night mode
        black → red, so the waterfall doesn't spoil night vision (v1.1.40)."""
        night = THEME.mode == "night"
        if night == self.lut_night:
            return
        self.lut_night = night
        if night:
            stops = [(0, (0, 0, 0)), (90, (60, 0, 0)), (180, (170, 0, 0)), (255, (255, 30, 20))]
        else:
            stops = [(0, (0, 0, 0)), (60, (10, 30, 140)), (120, (0, 170, 220)),
                     (175, (240, 230, 40)), (225, (235, 50, 20)), (255, (255, 255, 255))]
        self.lut = []
        for v in range(256):
            for (a, ca), (b, cb) in zip(stops, stops[1:]):
                if a <= v <= b:
                    f = (v - a) / (b - a)
                    r, g, bl = (round(ca[k] + (cb[k] - ca[k]) * f) for k in range(3))
                    # QImage Format_RGB32 is stored as B, G, R, 0xFF bytes.
                    self.lut.append(bytes((bl, g, r, 255)))
                    break

    def clear(self, message="Waterfall not active"):
        self.rows = bytearray(len(self.rows))
        self.row_count = 0
        self.current = None
        self.floor = None
        self.message = message
        self.update()

    def set_band(self, lower, upper, marker, step):
        if lower is None or upper is None or upper <= lower:
            self.lower = self.upper = None
            self.clear("Waterfall not active")
            return
        if (lower, upper) != (self.lower, self.upper):
            # New span or center: the old history no longer lines up.
            self.lower, self.upper = lower, upper
            self.clear("Waiting for graph data…")
        self.marker, self.step = marker, step
        self.update()

    def add_frame(self, values):
        if self.lower is None or len(values) != GRAPH_BINS:
            return
        self.current = values
        # Auto contrast: track the noise floor (25th percentile) smoothly.
        p25 = sorted(values)[GRAPH_BINS // 4]
        self.floor = p25 if self.floor is None else self.floor * 0.9 + p25 * 0.1
        low, span = self.floor - 8, 140
        self.build_lut()
        row = b"".join(self.lut[max(0, min(255, int((v - low) * 255 / span)))] for v in values)
        self.rows[len(row):] = self.rows[:-len(row)]     # scroll down one row
        self.rows[:len(row)] = row
        self.row_count = min(self.HISTORY, self.row_count + 1)
        self.update()

    def x_for(self, mhz, width):
        return (mhz - self.lower) / (self.upper - self.lower) * width

    def mhz_at(self, x):
        if self.lower is None:
            return None
        mhz = self.lower + max(0.0, min(1.0, x / max(1, self.width()))) * (self.upper - self.lower)
        if self.step:
            mhz = round(mhz / self.step) * self.step
            # Snapping can land just outside the span at the edges; step back in.
            if mhz < self.lower:
                mhz += self.step
            elif mhz > self.upper:
                mhz -= self.step
        return round(mhz, 4)

    def paintEvent(self, event):
        p = QPainter(self)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, tc("#0d1117"))
        plot_h = h - self.AXIS
        fft_h = int(plot_h * 0.4)
        if self.lower is None or self.current is None:
            p.setPen(tc("#a5bdd2"))
            p.setFont(tf("Sans", 12))
            p.drawText(QRectF(0, 0, w, plot_h), Qt.AlignmentFlag.AlignCenter, self.message)
        else:
            # FFT trace with level grid (0-255 scale).
            p.setPen(QPen(tc("#2a3a4d"), 1))
            for level in (64, 128, 192):
                y = fft_h - level / 255 * fft_h
                p.drawLine(QPointF(0, y), QPointF(w, y))
            points = [QPointF(i * w / (GRAPH_BINS - 1), fft_h - v / 255 * fft_h)
                      for i, v in enumerate(self.current)]
            p.setPen(QPen(tc("#79d6bd"), 1.5))
            p.drawPolyline(QPolygonF(points))
            # Waterfall image, newest row at the top.
            pixels = bytes(self.rows)    # QImage uses this buffer; keep it alive
            image = QImage(pixels, GRAPH_BINS, self.HISTORY,
                           GRAPH_BINS * 4, QImage.Format.Format_RGB32)
            p.drawImage(QRectF(0, fft_h, w, plot_h - fft_h), image)
            # Marker line.
            if self.marker is not None and self.lower <= self.marker <= self.upper:
                x = self.x_for(self.marker, w)
                p.setPen(QPen(tc("#52dc95"), 2))
                p.drawLine(QPointF(x, 0), QPointF(x, plot_h))
                p.setFont(tf("Sans", 9, QFont.Weight.Bold))
                label = f"{self.marker:.4f}"
                lx = min(max(x + 4, 0), w - 70)
                p.drawText(QRectF(lx, 2, 70, 16), Qt.AlignmentFlag.AlignLeft, label)
        # Frequency axis.
        p.setPen(tc("#c8d7e8"))
        p.setFont(tf("Sans", 9))
        if self.lower is not None:
            mid = (self.lower + self.upper) / 2
            p.drawText(QRectF(2, plot_h, 120, self.AXIS), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, f"{self.lower:.4f}")
            p.drawText(QRectF(w / 2 - 60, plot_h, 120, self.AXIS), Qt.AlignmentFlag.AlignCenter, f"{mid:.4f} MHz")
            p.drawText(QRectF(w - 122, plot_h, 120, self.AXIS), Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter, f"{self.upper:.4f}")

    def mouseMoveEvent(self, event):
        mhz = self.mhz_at(event.position().x())
        if mhz is not None:
            QToolTip.showText(event.globalPosition().toPoint(),
                              f"{mhz:.4f} MHz — double-click to tune", self)

    def mouseDoubleClickEvent(self, event):
        mhz = self.mhz_at(event.position().x())
        if mhz is not None:
            self.tune_requested.emit(mhz)


class WaterfallWindow(QWidget):
    """Top-level waterfall window. Reports when it is shown or hidden."""
    visibility_changed = pyqtSignal(bool)

    def __init__(self, parent):
        super().__init__(parent, Qt.WindowType.Window)

    def showEvent(self, event):
        super().showEvent(event)
        self.visibility_changed.emit(True)

    def hideEvent(self, event):
        super().hideEvent(event)
        self.visibility_changed.emit(False)


class RotaryDial(QWidget):
    """Clickable rotary dial: left/right sectors rotate, center presses."""
    activated = pyqtSignal(str)

    def __init__(self):
        super().__init__()
        self.setMinimumSize(150, 126)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setToolTip("Click left to rotate backward, right to rotate forward, center to push")

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        factor = min(self.width() / 260, self.height() / 218)
        painter.translate((self.width() - 260 * factor) / 2,
                          (self.height() - 218 * factor) / 2)
        painter.scale(factor, factor)
        painter.setPen(QPen(tc("#7388a0"), 3))
        painter.setBrush(QBrush(tc("#263849")))
        painter.drawEllipse(41, 15, 178, 178)
        painter.setPen(QPen(tc("#8ec9e9"), 3))
        painter.setBrush(QBrush(tc("#435c77")))
        painter.drawEllipse(82, 56, 96, 96)
        painter.setPen(tc("#ffffff"))
        painter.setFont(tf("Sans", 13, QFont.Weight.Bold))
        painter.drawText(QRectF(88, 82, 84, 44),
                         Qt.AlignmentFlag.AlignCenter, "PUSH")
        painter.setFont(tf("Sans", 22, QFont.Weight.Bold))
        painter.drawText(QRectF(40, 77, 42, 45),
                         Qt.AlignmentFlag.AlignCenter, "‹")
        painter.drawText(QRectF(177, 77, 42, 45),
                         Qt.AlignmentFlag.AlignCenter, "›")
        painter.setFont(tf("Sans", 10))
        painter.drawText(QRectF(0, 195, 260, 20),
                         Qt.AlignmentFlag.AlignCenter, "ROTATE  •  PRESS")

    def mousePressEvent(self, event):
        if not self.isEnabled():
            return
        factor = min(self.width() / 260, self.height() / 218)
        x = (event.position().x() - (self.width() - 260 * factor) / 2) / factor
        y = (event.position().y() - (self.height() - 218 * factor) / 2) / factor
        if 82 <= x <= 178 and 56 <= y <= 152:
            self.activated.emit("^")
        elif 35 <= x < 82 and 55 <= y <= 160:
            self.activated.emit("<")
        elif 178 < x <= 225 and 55 <= y <= 160:
            self.activated.emit(">")


SERVICE_TYPES = [
    # PST1-PST37 in order, from Remote Command Specification V2.00 ("non" = unused).
    "Multi-Dispatch", "Law Dispatch", "Fire Dispatch", "EMS Dispatch", "non",
    "Multi-Tac", "Law Tac", "Fire-Tac", "EMS-Tac", "non", "Interop", "Hospital",
    "Ham", "Public Works", "Aircraft", "Federal", "Business", "non", "non",
    "Railroad", "Other", "Multi-Talk", "Law Talk", "Fire-Talk", "EMS-Talk",
    "Transportation", "non", "non", "Emergency Ops", "Military", "Media",
    "Schools", "Security", "Utilities", "non", "non", "Corrections",
]
CUSTOM_SERVICE_TYPES = ["Custom 1", "Custom 2", "Custom 3", "Custom 4", "Custom 5",
                        "Custom 6", "Custom 7", "Custom 8", "Racing Officials", "Racing Teams"]

LIST_KINDS = {
    # GLT list type -> (display name, child lists to request when expanded)
    "FL": ("Favorites List", ("SYS",)),
    "SYS": ("System", ("DEPT", "SITE")),
    "DEPT": ("Department", ("CFREQ", "TGID")),
    "SITE": ("Site", ("SFREQ",)),
    "CFREQ": ("Channel", ()),
    "TGID": ("Talkgroup", ()),
    "SFREQ": ("Site frequency", ()),
}
HOLDABLE = ("SYS", "DEPT", "SITE", "CFREQ", "TGID")

# ---- Scanner Tools → Avoids (1.1.77) ---------------------------------------------------------------
# Reads the whole Favorites tree with GLT (lists → systems → sites and departments → channels and
# talkgroups) and shows every avoidable item in one table, to avoid or un-avoid many at once with AVD
# (status 1 permanent, 2 temporary, 3 remove; remote command specification V2.00).
AVOID_GROUPS = {"SYS": "Systems", "SITE": "Sites", "DEPT": "Departments", "CFREQ": "Channels",
                "TGID": "Talkgroups"}
AVOID_STATUS = {1: "Permanent", 2: "Temporary", 3: "Off"}


def avoid_state(value):
    """'Off', 'Temporary' or 'Permanent' from a GLT Avoid attribute."""
    text = str(value or "").strip()
    if text.casefold() in ("", "off", "none", "0", "—"):
        return "Off"
    if text.upper().startswith("T") or "temp" in text.casefold():
        return "Temporary"
    return "Permanent"


def avoid_children(kind, sys_type, leaves=True):
    """GLT lists to read under an item when looking for avoids."""
    conventional = "conv" in str(sys_type or "").lower()
    if kind == "FL":
        return ("SYS",)
    if kind == "SYS":
        return ("DEPT",) if conventional else ("DEPT", "SITE")
    if kind == "DEPT" and leaves:
        return ("CFREQ",) if conventional else ("TGID",) if sys_type else ("CFREQ", "TGID")
    return ()


def avoid_row(element, where, sys_type):
    a = element.attrib
    kind = element.tag
    name = (a.get("Name") or a.get("Freq") or a.get("TGID") or "(unnamed)").strip()
    details = {"SYS": a.get("Type", ""), "CFREQ": a.get("Freq", "").strip(), "TGID": f"TGID {a.get('TGID', '')}",
               "SITE": "", "DEPT": ""}.get(kind, "")
    return {"kind": kind, "name": name, "where": where, "details": details, "index": a.get("Index", ""),
            "avoid": avoid_state(a.get("Avoid")), "sys_type": sys_type}


def avoid_filter(rows, kinds, avoided_only=True, text=""):
    text = str(text or "").strip().casefold()
    return [r for r in rows if r["kind"] in kinds and (not avoided_only or r["avoid"] != "Off")
            and (not text or text in (r["name"] + " " + r["where"] + " " + r["details"]).casefold())]


# ---- names, number tags and scan profiles from SDS-Manager (1.1.68) ---------------------------------
# SDS-Manager writes this file whenever its open configuration is saved or its scan profiles change. The
# Monitor only reads it. Names come from the configuration as saved there, so they match the scanner once
# that configuration has been exported.
MANAGER_KEYS_FILE = (Path.home() / ".local" / "share" / "sds100-database-favorites-manager"
                     / "monitor-keys.json")


QK_BUTTON_WIDTH = 236          # 1.1.69: wide enough for a county name; longer names end in …
QK_COLUMNS = 4                 # four across fits the Scanner Tools window


def fit_text(widget, text, width):
    """text shortened with … to fit width pixels in the widget's font (whole text if it fits)."""
    try:
        fitted = widget.fontMetrics().elidedText(text, Qt.TextElideMode.ElideRight, width)
    except (AttributeError, TypeError):
        fitted = None
    return fitted if isinstance(fitted, str) else (text if len(text) <= 22 else text[:21] + "…")


def load_manager_keys(path=None):
    """The Manager's shared keys file as a dict, or {} if there is none (or it can't be read)."""
    try:
        data = json.loads(Path(path or MANAGER_KEYS_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) and isinstance(data.get("lists"), list) else {}


def scanner_sync_warning(data, list_type="", list_name=""):
    """1.1.74: a line when the scanner and SDS-Manager's configuration seem out of step, else "".

    data is SDS-Manager's shared file (load_manager_keys). Two signs, both only hints:
      - SDS-Manager saved changes it hasn't exported to the scanner yet (SDS-Manager 0.1.20 or later);
      - the scanner is playing a Favorites List (GSI MonitorList, ListType FL) that isn't in the
        configuration SDS-Manager has open."""
    if not data:
        return ""
    config = str(data.get("configuration") or "SDS-Manager's configuration")
    scanner = data.get("scanner") if isinstance(data.get("scanner"), dict) else {}
    if scanner.get("state") == "changed":
        saved = str(scanner.get("saved") or "").replace("T", " ")[:16]
        return (f"Scanner out of date: {config} has changes saved in SDS-Manager"
                + (f" ({saved})" if saved else "") + " that aren't on the scanner yet. "
                "Use Export to Scanner in SDS-Manager.")
    name = str(list_name or "").strip()
    if list_type == "FL" and name and name != "—":
        names = {str(l.get("name") or "").strip().casefold() for l in data.get("lists", [])}
        if names and name.casefold() not in names:
            return (f"The scanner is playing Favorites List \"{name}\", which isn't in {config} in "
                    "SDS-Manager. The scanner may have a different configuration: read it from the scanner "
                    "in SDS-Manager, or export yours to it.")
    return ""


def manager_list(data, fl_key):
    return next((l for l in data.get("lists", []) if l.get("key") == fl_key), None)


def manager_system(data, fl_key, sys_key):
    favorites = manager_list(data, fl_key)
    if favorites is None:
        return None
    return next((s for s in favorites.get("systems", []) if s.get("key") == sys_key), None)


def manager_key_names(data, code, fl_key=None, sys_key=None):
    """{quick key: name} for FQK (lists), SQK (systems of the list on fl_key) or DQK (departments of the
    system on sys_key in that list). Several items on one key are joined with ' + '."""
    if code == "FQK":
        items = data.get("lists", [])
    elif code == "SQK":
        items = (manager_list(data, fl_key) or {}).get("systems", [])
    else:
        items = (manager_system(data, fl_key, sys_key) or {}).get("departments", [])
    names = {}
    for item in items:
        key = item.get("key")
        if isinstance(key, int):
            names[key] = names[key] + " + " + item["name"] if key in names else item["name"]
    return names


def manager_tag_choices(data):
    """[(label, (list tag, system tag, channel tag))] for Go to Number Tag; None = leave blank."""
    out = []
    for favorites in data.get("lists", []):
        lt = favorites.get("tag")
        if lt is None:
            continue
        out.append((f"{lt} — {favorites['name']} (whole list)", (lt, None, None)))
        for system in favorites.get("systems", []):
            st = system.get("tag")
            if st is None:
                continue
            out.append((f"{lt}/{st} — {system['name']} ({favorites['name']})", (lt, st, None)))
            for channel in sorted(system.get("channels", []), key=lambda c: c.get("tag", 0)):
                out.append((f"{lt}/{st}/{channel['tag']} — {channel['name']} ({system['name']})",
                            (lt, st, channel["tag"])))
    return out


def profile_steps(data, profile):
    """Scanner commands to apply a scan profile: [(code, read command, set prefix, wanted On/Off x100)].
    Systems and departments are reached by their list's and system's quick keys, so items without a
    quick key are skipped (the scanner can't switch them by key)."""
    steps = []
    fl = profile.get("fl")
    if isinstance(fl, list) and len(fl) == 100:
        steps.append(("FQK", "FQK", "FQK,", [bool(v) for v in fl]))
    for favorites in data.get("lists", []):
        lk = favorites.get("key")
        if lk is None:
            continue
        wanted = profile.get("sys", {}).get(favorites.get("filename"))
        if isinstance(wanted, list) and len(wanted) == 100:
            steps.append(("SQK", f"SQK,{lk}", f"SQK,{lk},", [bool(v) for v in wanted]))
        for system in favorites.get("systems", []):
            sk = system.get("key")
            wanted = profile.get("dept", {}).get(f"{favorites.get('filename')}|{system['name']}")
            if sk is not None and isinstance(wanted, list) and len(wanted) == 100:
                steps.append(("DQK", f"DQK,{lk},{sk}", f"DQK,{lk},{sk},", [bool(v) for v in wanted]))
    return steps


def step_names(data, step):
    """{key: name} for the set of quick keys one profile step switches."""
    code, read = step[0], step[1]
    parts = [int(p) for p in read.split(",")[1:]]
    return manager_key_names(data, code, *parts)


def profile_change_lines(data, step, current, wanted):
    """Plain lines for the keys one step turns On or Off (1.1.79)."""
    names = step_names(data, step)
    where = {"FQK": "Favorites List keys", "SQK": "System keys", "DQK": "Department keys"}[step[0]]
    if step[0] == "SQK":
        where += " in " + (manager_key_names(data, "FQK").get(int(step[1].split(",")[1])) or step[1])
    elif step[0] == "DQK":
        _c, fl, sk = step[1].split(",")
        where += " in " + (manager_key_names(data, "SQK", int(fl)).get(int(sk)) or step[1])
    lines = []
    for verb, value in (("On", 2), ("Off", 1)):
        keys = [n for n, (was, now) in enumerate(zip(current, wanted)) if was != now and now == value]
        if keys:
            lines.append(f"{where} — {verb}: " + ", ".join(
                f"{k:02d}" + (f" {names[k]}" if k in names else "") for k in keys))
    return lines


def merged_quick_keys(current, wanted):
    """The scanner's 100 statuses (0 none, 1 off, 2 on) with assigned keys set as wanted."""
    return [st if st not in (1, 2) else (2 if want else 1) for st, want in zip(current, wanted)]


class ScannerTools(QWidget):
    """View → Scanner Tools…: lists, quick keys, service types, location, alerts.

    Reads and changes the scanner's live configuration over the serial link
    (GLT, HLD, AVD, FQK/SQK/DQK, SVC, LCR from spec V2.00).
    """

    def __init__(self, monitor):
        super().__init__(monitor, Qt.WindowType.Window)
        self.monitor = monitor
        self.setWindowTitle(f"SDS100 Scanner Tools — SDS100 Monitor v{VERSION}")
        icon_file = Path(__file__).with_name("sds100-monitor.svg")
        if icon_file.exists():
            self.setWindowIcon(QIcon(str(icon_file)))
        self.resize(1000, 720)
        layout = QVBoxLayout(self)
        self.tabs = QTabWidget()
        layout.addWidget(self.tabs, 1)
        self.status = make_label("Connect to the scanner to use these tools.")
        self.status.setWordWrap(True)
        layout.addWidget(self.status)
        self.glt_pending = deque()      # (command, parent item) in request order
        self.fl_by_qk = {}              # favorites list quick key -> name
        self.manager_keys = load_manager_keys()
        self.profile_run = None         # a scan profile being applied (1.1.68)
        self.build_lists_tab()
        self.build_avoids_tab()
        self.build_quickkeys_tab()
        self.build_service_tab()
        self.build_location_tab()

    def send(self, command):
        if self.monitor.queue(command):
            return True
        set_text(self.status, "Not connected — nothing was sent.")
        return False

    # ---- Lists ---------------------------------------------------------------
    def build_lists_tab(self):
        tab = QWidget()
        layout = QVBoxLayout(tab)
        row = QHBoxLayout()
        load = QPushButton("LOAD FAVORITES LISTS")
        load.clicked.connect(self.load_favorites)
        row.addWidget(load)
        row.addWidget(make_label("Expand an item to load what's inside it. Right-click to hold or avoid."))
        row.addStretch(1)
        layout.addLayout(row)
        self.tree = QTreeWidget()
        self.tree.setColumnCount(6)
        self.tree.setHeaderLabels(["Name", "Type", "Details", "Avoid", "Quick key", "Index"])
        self.tree.header().setSectionResizeMode(0, QHeaderView.ResizeMode.Interactive)
        self.tree.setColumnWidth(0, 330)
        self.tree.setColumnWidth(1, 120)
        self.tree.setColumnWidth(2, 230)
        self.tree.itemExpanded.connect(self.expand_item)
        self.tree.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.tree.customContextMenuRequested.connect(self.tree_menu)
        layout.addWidget(self.tree, 1)
        self.tabs.addTab(tab, "Lists")

    def load_favorites(self):
        if any(isinstance(p, dict) for _c, p in self.glt_pending):
            set_text(self.status, "Wait for READ AVOIDS to finish (or press STOP) first.")
            return
        self.tree.clear()
        self.glt_pending.clear()
        self.request_list("GLT,FL", None)

    def request_list(self, command, parent):
        if self.monitor.request_glt("tools", command):
            self.glt_pending.append((command, parent))
            set_text(self.status, f"Requested {command}…")
        else:
            set_text(self.status, "Not connected — nothing was sent.")

    def make_item(self, element, parent):
        kind = element.tag
        a = element.attrib
        name = a.get("Name") or a.get("Freq") or a.get("TGID") or "(unnamed)"
        details = {
            "FL": f"Monitor {a.get('Monitor', '—')}",
            "SYS": a.get("Type", ""),
            "CFREQ": " • ".join(x for x in (a.get("Freq", "").strip(), a.get("Mod", ""),
                                             a.get("SvcType", "")) if x),
            "TGID": " • ".join(x for x in (a.get("TGID", ""), a.get("SvcType", "")) if x),
            "SFREQ": a.get("Freq", "").strip(),
        }.get(kind, "")
        item = QTreeWidgetItem([name.strip(), LIST_KINDS.get(kind, (kind,))[0], details,
                                a.get("Avoid", ""), a.get("Q_Key", ""), a.get("Index", "")])
        item.setData(0, Qt.ItemDataRole.UserRole, {"kind": kind, "attrs": dict(a),
                                                    "loaded": False})
        if LIST_KINDS.get(kind, ("", ()))[1]:
            item.addChild(QTreeWidgetItem(["(expand to load)"]))
        if parent is None:
            self.tree.addTopLevelItem(item)
        else:
            parent.addChild(item)
        if kind == "FL" and a.get("Q_Key", "None").isdigit():
            self.fl_by_qk[int(a["Q_Key"])] = name.strip()
        return item

    def item_info(self, item):
        return item.data(0, Qt.ItemDataRole.UserRole) if item else None

    def expand_item(self, item):
        info = self.item_info(item)
        if not info or info["loaded"]:
            return
        info["loaded"] = True
        item.setData(0, Qt.ItemDataRole.UserRole, info)
        item.takeChildren()
        item.addChild(QTreeWidgetItem(["Loading…"]))
        index = info["attrs"].get("Index", "")
        children = LIST_KINDS[info["kind"]][1]
        if info["kind"] == "SYS":
            sys_type = info["attrs"].get("Type", "").lower()
            if "conv" in sys_type:
                children = ("DEPT",)             # conventional systems have no sites
        if info["kind"] == "DEPT":
            parent_info = self.item_info(item.parent())
            sys_type = (parent_info or {}).get("attrs", {}).get("Type", "").lower()
            if "conv" in sys_type:
                children = ("CFREQ",)
            elif sys_type:
                children = ("TGID",)
        for child in children:
            self.request_list(f"GLT,{child},{index}", item)

    def handle_list(self, xml):
        if not self.glt_pending:
            return
        command, parent = self.glt_pending.popleft()
        try:
            root = ET.fromstring(xml)
        except ET.ParseError:
            set_text(self.status, f"{command}: the scanner's list could not be read.")
            if isinstance(parent, dict):
                self.avoid_scan_step()
            return
        if isinstance(parent, dict):            # Avoids tab scan (1.1.77)
            self.avoids_received(command, parent, root)
            return
        footer = root.find("Footer")
        if parent is not None:
            # Remove the "Loading…" placeholder on the first part received.
            for i in reversed(range(parent.childCount())):
                if parent.child(i).data(0, Qt.ItemDataRole.UserRole) is None:
                    parent.takeChild(i)
        count = 0
        for element in root:
            if element.tag == "Footer":
                continue
            self.make_item(element, parent)
            count += 1
        if footer is not None and footer.attrib.get("EOT", "1") == "0":
            # Long lists arrive in parts: ask again for the next part. The
            # request goes to the back of the queue, so its reply comes after
            # any GLT replies already on the way.
            if self.monitor.request_glt("tools", command):
                self.glt_pending.append((command, parent))
        set_text(self.status, f"{command}: {count} item(s) received.")
        if parent is not None and parent.childCount() == 0 and not any(
                cmd for cmd, p in self.glt_pending if p is parent):
            parent.addChild(QTreeWidgetItem(["(empty)"]))

    def handle_list_error(self, body):
        if not self.glt_pending:
            return
        command, parent = self.glt_pending.popleft()
        set_text(self.status, f"{command}: scanner replied {body}.")
        if isinstance(parent, dict):            # an empty list during an Avoids scan
            self.avoid_scan_step()
            return
        if parent is not None and not any(p is parent for _, p in self.glt_pending):
            for i in reversed(range(parent.childCount())):
                if parent.child(i).data(0, Qt.ItemDataRole.UserRole) is None:
                    parent.takeChild(i)
            if parent.childCount() == 0:
                parent.addChild(QTreeWidgetItem(["(nothing to show)"]))

    def tree_menu(self, point):
        item = self.tree.itemAt(point)
        info = self.item_info(item)
        if not info:
            return
        kind, attrs = info["kind"], info["attrs"]
        index = attrs.get("Index", "")
        name = item.text(0)
        menu = QMenu(self)
        connected = self.monitor.connected
        if kind in HOLDABLE and index.isdigit():
            menu.addAction(f"Hold on {LIST_KINDS[kind][0]}",
                           lambda: self.list_command(f"HLD,{kind},{index},", name)).setEnabled(connected)
            menu.addSeparator()
            menu.addAction("Temporary Avoid",
                           lambda: self.avoid(item, kind, index, 2)).setEnabled(connected)
            menu.addAction("Permanent Avoid…",
                           lambda: self.avoid(item, kind, index, 1)).setEnabled(connected)
            menu.addAction("Remove Avoid",
                           lambda: self.avoid(item, kind, index, 3)).setEnabled(connected)
        if kind in ("CFREQ", "TGID"):
            menu.addSeparator()
            menu.addAction("Alert When This Is Active",
                           lambda: self.monitor.add_alert_rule("Channel", "is", name))
        menu.addSeparator()
        menu.addAction("Copy Name", lambda: copy_text(name))
        if item.parent() is not None or kind == "FL":
            menu.addAction("Refresh", lambda: self.refresh_item(item))
        menu.exec(self.tree.viewport().mapToGlobal(point))

    def list_command(self, command, name):
        if self.send(command):
            self.monitor.command_reply(f"QUEUED: {command} ({name})")
            set_text(self.status, f"Sent {command} for {name}.")

    def avoid(self, item, kind, index, status):
        name = item.text(0)
        if status == 1:
            reply = QMessageBox.question(
                self, "Permanent avoid",
                f"Permanently avoid {name}?\n\nIt stays avoided until you remove the avoid, "
                "including after the scanner is turned off.")
            if reply != QMessageBox.StandardButton.Yes:
                return
        self.list_command(f"AVD,{kind},{index},,{status}", name)
        if status in (1, 3):
            # 1.1.75: the scanner keeps a permanent avoid in its Favorites List file; SDS-Manager 0.1.21
            # offers to keep it in your configuration at the next Export to Scanner instead of undoing it.
            set_text(self.status, f"Sent AVD for {name}. SDS-Manager (0.1.21 or later) offers to keep "
                                  "this in your configuration at the next Export to Scanner.")
        parent = item.parent()
        QTimer.singleShot(900, lambda: self.refresh_item(parent) if parent else self.load_favorites())

    def refresh_item(self, item):
        if item is None:
            return
        info = self.item_info(item)
        if info is None:
            return
        info["loaded"] = False
        item.setData(0, Qt.ItemDataRole.UserRole, info)
        item.setExpanded(True)
        self.expand_item(item)

    # ---- Avoids (1.1.77) ------------------------------------------------------------
    def build_avoids_tab(self):
        tab = QWidget()
        layout = QVBoxLayout(tab)
        note = make_label("Every system, site, department, channel and talkgroup in the scanner's Favorites "
                          "Lists, read with READ AVOIDS. Select one or more rows (Ctrl/Shift+click) and avoid "
                          "them or remove their avoids. Temporary avoids end when the scanner is turned off.")
        note.setWordWrap(True)
        layout.addWidget(note)
        row = QHBoxLayout()
        self.avoid_read = QPushButton("READ AVOIDS")
        self.avoid_read.clicked.connect(self.scan_avoids)
        row.addWidget(self.avoid_read)
        self.avoid_stop = QPushButton("STOP")
        self.avoid_stop.clicked.connect(self.stop_avoid_scan)
        self.avoid_stop.setEnabled(False)
        row.addWidget(self.avoid_stop)
        self.avoid_leaves = QCheckBox("Include channels and talkgroups (slower)")
        self.avoid_leaves.setChecked(True)
        row.addWidget(self.avoid_leaves)
        row.addStretch(1)
        layout.addLayout(row)
        row = QHBoxLayout()
        self.avoid_only = QCheckBox("Avoided only")
        self.avoid_only.setChecked(False)
        self.avoid_only.toggled.connect(self.render_avoids)
        row.addWidget(self.avoid_only)
        self.avoid_kinds = {}
        for kind, label in AVOID_GROUPS.items():
            box = QCheckBox(label)
            box.setChecked(True)
            box.toggled.connect(self.render_avoids)
            self.avoid_kinds[kind] = box
            row.addWidget(box)
        self.avoid_search = QLineEdit()
        self.avoid_search.setPlaceholderText("Find…")
        self.avoid_search.textChanged.connect(self.render_avoids)
        row.addWidget(self.avoid_search, 1)
        layout.addLayout(row)
        self.avoid_table = QTableWidget(0, 5)
        self.avoid_table.setHorizontalHeaderLabels(["Avoid", "Type", "Name", "Where", "Details"])
        self.avoid_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
        self.avoid_table.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.avoid_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        self.avoid_table.setSortingEnabled(True)
        self.avoid_table.horizontalHeader().setStretchLastSection(True)
        for column, width in ((0, 100), (1, 110), (2, 260), (3, 330)):
            self.avoid_table.setColumnWidth(column, width)
        self.avoid_table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.avoid_table.customContextMenuRequested.connect(self.avoid_menu)
        layout.addWidget(self.avoid_table, 1)
        row = QHBoxLayout()
        for label, status in (("TEMPORARY AVOID", 2), ("PERMANENT AVOID…", 1), ("REMOVE AVOID", 3)):
            button = QPushButton(label)
            button.clicked.connect(lambda _c=False, st=status: self.avoid_selected(st))
            row.addWidget(button)
        clear = QPushButton("REMOVE ALL TEMPORARY AVOIDS…")
        clear.clicked.connect(self.clear_temporary_avoids)
        row.addWidget(clear)
        row.addStretch(1)
        self.avoid_count = make_label("")
        row.addWidget(self.avoid_count)
        layout.addLayout(row)
        self.avoid_rows = []
        self.avoid_scanning = False
        self.tabs.addTab(tab, "Avoids")

    def scan_avoids(self):
        """Read the whole Favorites tree for avoids. Replies come back through handle_list."""
        if not self.monitor.connected:
            set_text(self.status, "Not connected — nothing was sent.")
            return
        self.avoid_rows = []
        self.avoid_scanning = True
        self.avoid_read.setEnabled(False)
        self.avoid_stop.setEnabled(True)
        self.render_avoids()
        self.request_list("GLT,FL", {"kind": "", "where": "", "sys_type": ""})

    def stop_avoid_scan(self):
        self.avoid_scanning = False
        self.avoid_stop.setEnabled(False)
        set_text(self.status, "Stopping: waiting for the lists already asked for…")
        self.avoid_scan_step()

    def avoids_received(self, command, context, root):
        footer = root.find("Footer")
        if footer is not None and footer.attrib.get("EOT", "1") == "0" and self.avoid_scanning:
            if self.monitor.request_glt("tools", command):
                self.glt_pending.append((command, context))
        for element in root:
            kind = element.tag
            if kind == "Footer":
                continue
            name = (element.attrib.get("Name") or element.attrib.get("Freq") or "").strip()
            sys_type = element.attrib.get("Type", "") if kind == "SYS" else context["sys_type"]
            where = context["where"]
            if kind in AVOID_GROUPS:
                self.avoid_rows.append(avoid_row(element, where, sys_type))
            index = element.attrib.get("Index", "")
            if not self.avoid_scanning or not index:
                continue
            child = {"kind": kind, "where": f"{where} › {name}" if where else name, "sys_type": sys_type}
            for list_kind in avoid_children(kind, sys_type, self.avoid_leaves.isChecked()):
                self.request_list(f"GLT,{list_kind},{index}", child)
        self.avoid_scan_step()

    def avoid_scan_step(self):
        """After each reply: progress, and the table once nothing more is on the way."""
        waiting = sum(1 for _c, p in self.glt_pending if isinstance(p, dict))
        if waiting and self.avoid_scanning:
            set_text(self.status, f"Reading avoids: {len(self.avoid_rows)} item(s), {waiting} list(s) to go…")
            return
        if not self.avoid_scanning and waiting:
            return                                  # replies still on the way are dropped as they arrive
        stopped = not self.avoid_scanning
        self.avoid_scanning = False
        self.avoid_read.setEnabled(True)
        self.avoid_stop.setEnabled(False)
        self.render_avoids()
        avoided = sum(1 for r in self.avoid_rows if r["avoid"] != "Off")
        set_text(self.status, f"{'Stopped: ' if stopped else ''}{len(self.avoid_rows)} item(s) read, "
                              f"{avoided} avoided.")

    def shown_avoid_rows(self):
        kinds = {k for k, box in self.avoid_kinds.items() if box.isChecked()}
        return avoid_filter(self.avoid_rows, kinds, self.avoid_only.isChecked(), self.avoid_search.text())

    def render_avoids(self, *_args):
        table = getattr(self, "avoid_table", None)
        if table is None:
            return
        rows = self.shown_avoid_rows()
        position = {id(entry): number for number, entry in enumerate(self.avoid_rows)}
        table.setSortingEnabled(False)
        table.setRowCount(len(rows))
        colours = {"Permanent": "#c62828", "Temporary": "#ef6c00"}
        for r, entry in enumerate(rows):
            values = (entry["avoid"], LIST_KINDS[entry["kind"]][0], entry["name"], entry["where"], entry["details"])
            for c, value in enumerate(values):
                cell = QTableWidgetItem(value)
                cell.setData(Qt.ItemDataRole.UserRole, position[id(entry)])
                if c == 0 and value in colours:
                    cell.setForeground(QColor(colours[value]))
                table.setItem(r, c, cell)
        table.setSortingEnabled(True)
        avoided = sum(1 for e in rows if e["avoid"] != "Off")
        set_text(self.avoid_count, f"{len(rows)} shown, {avoided} avoided")

    def selected_avoid_rows(self):
        picked = set()
        for index in self.avoid_table.selectedIndexes():
            cell = self.avoid_table.item(index.row(), 0)
            if cell is not None:
                picked.add(cell.data(Qt.ItemDataRole.UserRole))
        return [self.avoid_rows[i] for i in sorted(picked) if isinstance(i, int) and 0 <= i < len(self.avoid_rows)]

    def avoid_menu(self, point):
        menu = QMenu(self)
        for label, status in (("Temporary Avoid", 2), ("Permanent Avoid…", 1), ("Remove Avoid", 3)):
            menu.addAction(label, lambda st=status: self.avoid_selected(st)).setEnabled(self.monitor.connected)
        menu.exec(self.avoid_table.viewport().mapToGlobal(point))

    def avoid_selected(self, status):
        self.send_avoids(self.selected_avoid_rows(), status)

    def clear_temporary_avoids(self):
        self.send_avoids([r for r in self.avoid_rows if r["avoid"] == "Temporary"], 3,
                         "Remove all {n} temporary avoid(s)?")

    def send_avoids(self, rows, status, question=None):
        """AVD for each row; the table shows the new state straight away (READ AVOIDS to check)."""
        rows = [r for r in rows if r["index"].isdigit() and (status != 3 or r["avoid"] != "Off")]
        if not rows:
            set_text(self.status, "Nothing to change: select rows first (avoided ones, to remove an avoid).")
            return 0
        if status == 1:
            question = ("Permanently avoid {n} item(s)?\n\nThey stay avoided until you remove the avoid, "
                        "including after the scanner is turned off.")
        elif question is None and len(rows) > 10:
            question = AVOID_STATUS[status] + " avoid for {n} item(s)?" if status != 3 else \
                "Remove the avoid from {n} item(s)?"
        if question and QMessageBox.question(self, "Avoids", question.format(n=len(rows))) \
                != QMessageBox.StandardButton.Yes:
            return 0
        sent = 0
        for entry in rows:
            if not self.send(f"AVD,{entry['kind']},{entry['index']},,{status}"):
                break
            entry["avoid"] = AVOID_STATUS[status]
            sent += 1
        self.render_avoids()
        if sent:
            self.monitor.command_reply(f"QUEUED: {sent} AVD command(s)")
            set_text(self.status, f"{AVOID_STATUS[status] if status != 3 else 'Avoid removed'}: {sent} item(s)."
                     + (" SDS-Manager (0.1.21 or later) offers to keep permanent avoids in your configuration "
                        "at the next Export to Scanner." if status in (1, 3) else ""))
        return sent

