                    ("F7", ("F", "7"), "FUNC + 7: IF Exchange"),
                    ("F9", ("F", "9"), "FUNC + 9: simple / detailed display"),
                    ("F0", ("F", "0"), "FUNC + 0: channel volume offset"),
