    def history_details(self, row_index, _column):
        row = [self.table.item(row_index, c).text() if self.table.item(row_index, c) else ""
               for c in range(len(HEADERS))]
        show_reception_details(self, row, self.history_search.setText)

    def history_context_menu(self, point):
        row = selected_record(self.table, point)
        menu = QMenu(self)
        if row:
            clicked = self.table.itemAt(point)
            menu.addAction("Copy Selected Cell", lambda: copy_text(clicked.text()))
            add_copy_actions(menu, row)
            menu.addSeparator()
            menu.addAction("Search for This Channel", lambda: set_text(self.history_search, row[5]))
            menu.addAction("Search for This System", lambda: set_text(self.history_search, row[3]))
            try:
                row_mhz = self.validate_mhz(row[6])
            except ValueError:
                row_mhz = None
            hold_freq = menu.addAction(
                f"Hold on This Frequency ({row_mhz:.4f} MHz)" if row_mhz else "Hold on This Frequency",
                lambda: self.tune_frequency(row_mhz))
            hold_freq.setEnabled(bool(row_mhz and self.connected))
            menu.addAction("Alert When This Channel Is Active",
                           lambda: self.add_alert_rule("Channel", "is", row[5]))
            if row[7] not in ("", "—"):
                menu.addAction("Alert When This Talkgroup Is Active",
                               lambda: self.add_alert_rule("Talkgroup", "is", row[7]))
            menu.addAction("View Reception Details…", lambda: show_reception_details(self, row, self.history_search.setText))
            menu.addAction("Export Selected Record…", lambda: export_csv_rows(self, [row]))
            recording = find_recording(row)
            play = menu.addAction("Play Recording" if recording else "Play Recording (none saved)",
                                  lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(str(recording))))
            play.setEnabled(recording is not None)
            units = units_for_reception(row)
            if units:
                menu.addSeparator()
                for key in units:
                    self.add_unit_menu(menu, key)
        menu.addSeparator()
        menu.addAction("Show All Records", self.history_search.clear).setEnabled(bool(self.history_search.text()))
        menu.addAction("Export Search Results…", lambda: export_csv_rows(self, self.visible_history_rows()))
        menu.addAction("Open History Archive Browser…", self.open_archive_browser)
        menu.addAction("Open Today's CSV File", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(str(daily_log_path(datetime.now()))))).setEnabled(daily_log_path(datetime.now()).exists())
        menu.addAction("Open History Folder", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(str(DAILY_LOG_DIR))))
        menu.exec(self.table.viewport().mapToGlobal(point))

    def visible_history_rows(self):
        return [[self.table.item(r, c).text() if self.table.item(r, c) else ""
                 for c in range(len(HEADERS))] for r in range(self.table.rowCount())]

    def stats_context_menu(self, point):
        item = self.stats_table.itemAt(point)
        menu = QMenu(self)
        if item:
            r = item.row()
            values = [self.stats_table.item(r, c).text() if self.stats_table.item(r, c) else "" for c in range(4)]
            menu.addAction("Copy Selected Statistic", lambda: copy_text(item.text()))
            menu.addAction("Copy Statistics Row", lambda: copy_text("\t".join(values)))
            menu.addAction("Show Reception History for Channel", lambda: set_text(self.history_search, values[0]))
            menu.addAction("Sort by Reception Count", lambda: self.stats_table.sortItems(2, Qt.SortOrder.DescendingOrder))
            menu.addAction("Sort by Total Duration", lambda: self.stats_table.sortItems(3, Qt.SortOrder.DescendingOrder))
            menu.addAction("Sort Alphabetically", lambda: self.stats_table.sortItems(0, Qt.SortOrder.AscendingOrder))
            menu.addSeparator()
        menu.addAction("Copy Statistics Table", lambda: copy_text("\n".join(
            "\t".join(self.stats_table.item(r, c).text() if self.stats_table.item(r, c) else ""
                       for c in range(4)) for r in range(self.stats_table.rowCount()))))
        menu.addAction("Export Statistics to CSV…", self.export_statistics)
        menu.addAction("Refresh Statistics", self.refresh_stats)
        menu.exec(self.stats_table.viewport().mapToGlobal(point))

    def export_statistics(self):
        path, _ = QFileDialog.getSaveFileName(self, "Export reception statistics", str(Path.home() / "reception_statistics.csv"), "CSV files (*.csv)")
        if not path:
            return
        try:
            with open(path, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(["Channel", "System", "Receptions", "Total time (s)"])
                for (channel, system), (count, duration) in sorted(self.statistics.items()):
                    writer.writerow([channel, system, count, f"{duration:.1f}"])
        except OSError as exc:
            QMessageBox.warning(self, "Export failed", str(exc))

    def open_archive_browser(self):
        if self.archive_browser is None or not self.archive_browser.isVisible():
            self.archive_browser = HistoryArchiveBrowser(self)
            self.archive_browser.show()
        else:
            self.archive_browser.refresh_files()
            self.archive_browser.raise_()
            self.archive_browser.activateWindow()

    # ---- SDS-Manager's names, number tags and profiles, reloaded when they change (1.1.73) -------
    def watch_manager_keys(self):
        from PyQt6.QtCore import QFileSystemWatcher
        self.keys_watcher = QFileSystemWatcher(self)
        self.keys_timer = QTimer(self)
        self.keys_timer.setSingleShot(True)
        self.keys_timer.setInterval(700)            # SDS-Manager replaces the file; wait for it to settle
        self.keys_timer.timeout.connect(self.manager_keys_changed)
        self.keys_watcher.fileChanged.connect(lambda _p: self.keys_timer.start())
        self.keys_watcher.directoryChanged.connect(lambda _p: self.keys_timer.start())
        self.rewatch_manager_keys()

    def rewatch_manager_keys(self):
        folder = MANAGER_KEYS_FILE.parent
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError:
            return
        watched = list(self.keys_watcher.files() or []) + list(self.keys_watcher.directories() or [])
        for path in (folder, MANAGER_KEYS_FILE):
            if path.exists() and str(path) not in watched:
                self.keys_watcher.addPath(str(path))

    def manager_keys_changed(self):
        """SDS-Manager saved its configuration or a scan profile: refresh what came from it."""
        self.rewatch_manager_keys()
        if hasattr(self, "jnt_pick"):
            self.fill_number_tags()
        tools = getattr(self, "scanner_tools", None)
        if tools is not None:
            tools.reload_manager_keys()
        self.update_sync_warning()
        self.statusBar().showMessage("Names, number tags and scan profiles updated from SDS-Manager.", 5000)

    def update_sync_warning(self):
        banner = getattr(self, "sync_banner", None)
        if banner is None:
            return
        text = scanner_sync_warning(load_manager_keys(), *self.sync_list)
        banner.setText(text)
        banner.setVisible(bool(text) and text != self.sync_dismissed)

    def dismiss_sync_warning(self):
        self.sync_dismissed = self.sync_banner.text()
        self.sync_banner.hide()

    # ---- the customizable Scanner Information panel (1.1.71) -------------------------------------
    def build_info_rows(self, layout):
        for _line, name, value in self.info_rows:
            for widget in (name, value):
                if widget is not None:
                    self.info_grid.removeWidget(widget)
                    widget.deleteLater()
        self.info_rows = []
        self.info_layout_now = layout
        for row, line in enumerate(layout["lines"]):
            name = make_label(line["label"]) if line["show_label"] else None
            value = make_label("—")
            value.setObjectName("value")
            value.setWordWrap(True)
            value.setProperty("size_pct", line["size"])
            value.setProperty("bold", line["bold"])
            value.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            value.customContextMenuRequested.connect(
                lambda pos, w=value: self.live_context_menu(w.mapToGlobal(pos)))
            if name is not None:
                self.info_grid.addWidget(name, row, 0)
                self.info_grid.addWidget(value, row, 1)
            else:
                self.info_grid.addWidget(value, row, 0, 1, 2)
            self.info_grid.setRowStretch(row, 1)
            self.info_rows.append((line, name, value))
        self.render_info()
        try:
            self.info_tab.rescale()          # apply the per-line sizes now, not only on the next resize
        except (AttributeError, TypeError):  # not laid out yet
            pass

    def info_now(self):
        values = dict(self.info_values)
        now = datetime.now()
        values["Clock"] = now.strftime("%H:%M:%S")
        reception = getattr(self, "reception", None)
        if reception:
            values["Reception Start"] = reception["start"].strftime("%H:%M:%S")
            values["Duration"] = f"{(now - reception['start']).total_seconds():.0f} s"
        else:
            values["Reception Start"] = values["Duration"] = "—"
        return values

    def render_info(self):
        layout = getattr(self, "info_layout_now", None)
        if layout is None:
            return
        values = self.info_now()
        panel, styles = info_styles(layout, values)
        set_css(self.info_tab, f"QWidget#infoPanel {{ background:{panel}; }}" if panel else "")
        for (line, name, value), (fg, bg) in zip(self.info_rows, styles):
            set_text(value, info_text(line, values))
            set_css(value, info_line_css(fg, bg, line["bold"]))
            if name is not None:
                set_css(name, f"color:{fg};" if fg else "")

    def customize_info_panel(self):
        dialog = InfoPanelDialog(self, self.info_settings, self.build_info_rows)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            self.info_settings = dialog.result_settings()
            try:
                save_info_settings(self.info_settings)
            except OSError as exc:
                self.statusBar().showMessage(f"Could not save the panel layout: {exc}", 8000)
        self.build_info_rows(self.info_settings["current"])

    def live_context_menu(self, global_point):
        """Read-only copying plus existing, connection-gated scanner commands."""
        menu = QMenu(self)
        for field in ("Channel", "Frequency", "System", "Site", "Department",
                      "Talkgroup", "Unit ID"):
            value = self.fields[field].text().strip()
            action = menu.addAction(f"Copy {field}",
                                    lambda checked=False, v=value: copy_text(v))
            action.setEnabled(bool(value and value != "—"))
        unit_key = uid_key(self.fields["Unit ID"].text())
        if unit_key:
            menu.addSeparator()
            self.add_unit_actions(menu, unit_key, hint=self.current_unit[1]
                                  if self.current_unit[0] == unit_key else "")
        menu.addSeparator()
        connected = bool(self.thread and self.thread.isRunning() and
                         self.status.text() != "DISCONNECTED")
        hold = menu.addAction("Hold on Current Channel",
                              lambda: self.control("channel_hold"))
        hold.setEnabled(connected and bool(getattr(self, "current_channel_index", None))
                        and bool(getattr(self, "current_channel_type", None)))
        scan = menu.addAction("Resume Scanning", lambda: self.control("scan"))
        scan.setEnabled(connected)
        menu.addSeparator()
        menu.addAction("Show Reception History", lambda: self.docks[0].raise_())
        menu.addAction("Browse History Archives…", self.open_archive_browser)
        menu.addSeparator()
        menu.addAction("Edit in Manager…", self.edit_current_in_manager)
        menu.addAction("Add to Favorites List in Manager…", self.add_current_in_manager)
        menu.addSeparator()
        menu.addAction("Customize This Panel…", self.customize_info_panel)
        menu.exec(global_point)

    def install_tab_context_menus(self):
        """Bind Qt's internal dock tab bars without replacing native docking."""
        for bar in self.findChildren(QTabBar):
            if bar.property("sds100_menu_bound"):
                continue
            bar.setProperty("sds100_menu_bound", True)
            bar.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            bar.customContextMenuRequested.connect(
                lambda point, b=bar: self.tab_context_menu(b, point))

    def tab_context_menu(self, bar, point):
        index = bar.tabAt(point)
        if index < 0:
            return
        title = bar.tabText(index).replace("&", "").strip()
        dock = next((d for d in self.docks if d.windowTitle() == title), None)
        if dock:
            self.dock_context_menu(dock, bar.mapToGlobal(point))

    def dock_context_menu(self, dock, global_point):
        menu = QMenu(self)
        if dock.isFloating():
            menu.addAction("Reattach Panel", lambda: self.attach_dock(dock))
        else:
            menu.addAction("Detach Panel", lambda: self.detach_dock(dock))
        menu.addAction("Hide This Panel", dock.hide)
        menu.addSeparator()
        menu.addAction("Show All Panels", self.show_all_docks)
        menu.addAction("Reset Panel Layout", self.reset_docks)
        menu.addAction("Save Current Layout", self.save_settings)
        menu.exec(global_point)

    def show_all_docks(self):
        for dock in self.docks:
            dock.show()
        QTimer.singleShot(0, self.install_tab_context_menus)

    def detach_dock(self, dock):
        dock.show()
        dock.setFloating(True)
        geometry = self.settings.value("floating/" + dock.objectName())
        if geometry:
            dock.restoreGeometry(geometry)
        else:
            dock.resize(max(520, dock.width()), max(500, dock.height()))
        dock.raise_()
        dock.activateWindow()
        QTimer.singleShot(0, self.install_tab_context_menus)

    def attach_dock(self, dock):
        if dock.isFloating():
            self.settings.setValue("floating/" + dock.objectName(),
                                   dock.saveGeometry())
        dock.setFloating(False)
        dock.show()
        self.addDockWidget(Qt.DockWidgetArea.BottomDockWidgetArea, dock)
        anchor = next((d for d in self.docks if d is not dock and not d.isFloating()),
                      None)
        if anchor is not None:
            self.tabifyDockWidget(anchor, dock)
        dock.raise_()
        QTimer.singleShot(0, self.install_tab_context_menus)

    def reset_docks(self):
        for dock in self.docks:
            if dock.isFloating():
                self.settings.setValue("floating/" + dock.objectName(),
                                       dock.saveGeometry())
            dock.setFloating(False)
            dock.show()
            self.addDockWidget(Qt.DockWidgetArea.BottomDockWidgetArea, dock)
        for other in self.docks[1:]:
            self.tabifyDockWidget(self.docks[0], other)
        self.docks[3].raise_()
        QTimer.singleShot(0, self.install_tab_context_menus)

    @staticmethod
    def valid_index(node):
        if node is None:
            return None
        raw = node.attrib.get("Index", "")
        return raw if raw.isdigit() and int(raw) != 4294967295 else None

    def build_control_panel(self, layout):
        group = QGroupBox("SCANNER CONTROL • click only when connected")
        grid = QGridLayout(group)
        buttons = [
            ("RESUME SCAN", "scan", "#1b8a5a", 0, 0),
            ("CHANNEL HOLD", "channel_hold", "#a87d15", 0, 1),
            ("SYSTEM HOLD", "system_hold", "#2167b1", 1, 0),
            ("DEPARTMENT HOLD", "dept_hold", "#2167b1", 1, 1),
            ("◀ PREVIOUS CHANNEL", "previous", "#566476", 2, 0),
            ("NEXT CHANNEL ▶", "next", "#566476", 2, 1),
            ("TEMPORARY AVOID", "avoid", "#bd6b23", 3, 0),
            ("REMOVE AVOID", "unavoid", "#7654a6", 3, 1),
        ]
        self.control_buttons = []
        self.unavoid_btn = None
        for label, action, color, row, col in buttons:
            btn = QPushButton(label)
            set_css(btn, f"QPushButton {{ background:{color}; color:white;"
                " font-weight:700; padding:10px; border-radius:6px; }"
                "QPushButton:disabled { background:#414750; color:#a4a9b0; }")
            btn.clicked.connect(lambda checked=False, a=action: self.control(a))
            btn.setEnabled(False)
            grid.addWidget(btn, row, col)
            self.control_buttons.append(btn)
            if action == "unavoid":
                self.unavoid_btn = btn
                btn.setToolTip("Removes the avoid from the channel most recently "
                               "avoided with TEMPORARY AVOID")
        self.command_status = make_label("Connect to enable controls.")
        grid.addWidget(self.command_status, 4, 0, 1, 2)
        layout.addWidget(group)
        self.build_scanner_settings(layout)
        self.build_number_tag(layout)


    # ---- Number tag jump (JNT) -------------------------------------------
    def build_number_tag(self, layout):
        box = QGroupBox("GO TO NUMBER TAG")
        grid = QGridLayout(box)
        self.jnt_boxes = []
        for col, (label, top) in enumerate((("Favorites list", 99), ("System", 99),
                                            ("Channel", 999))):
            grid.addWidget(make_label(label), 0, col)
            spin = QSpinBox()
            spin.setRange(-1, top)
            spin.setSpecialValueText("—")      # -1 = leave this tag blank
            spin.setValue(int(self.settings.value(f"jnt/{col}", -1)))
            spin.setToolTip(f"Number tag 0–{top}, or — to leave it out")
            grid.addWidget(spin, 1, col)
            self.jnt_boxes.append(spin)
        go = QPushButton("GO")
        set_css(go, "QPushButton { background:#1b8a5a; color:white; font-weight:700;"
                         " padding:8px; border-radius:6px; }"
                         "QPushButton:disabled { background:#414750; color:#a4a9b0; }")
        go.setToolTip("Jump to the channel with these number tags (JNT), like the "
                      "scanner's own number tag entry")
        go.clicked.connect(self.jump_number_tag)
        go.setEnabled(False)
        grid.addWidget(go, 1, 3)
        self.settings_controls.append(go)
        # 1.1.67: number tags are often mistaken for quick keys; say which is which.
        self.jnt_label = make_label(self.JNT_HINT)
        self.jnt_label.setWordWrap(True)
        grid.addWidget(self.jnt_label, 2, 0, 1, 3)
        keys = QPushButton("QUICK KEYS…")
        keys.setToolTip("Turn favorites list, system and department quick keys on and off "
                        "(Scanner Tools → Quick Keys)")
        keys.clicked.connect(self.open_quick_keys)
        grid.addWidget(keys, 2, 3)
        # 1.1.68: pick from what actually has number tags in SDS-Manager's configuration.
        self.jnt_pick = QComboBox()
        self.jnt_pick.setToolTip("Lists, systems and channels that have number tags in SDS-Manager's "
                                 "configuration; choosing one fills in the three numbers")
        self.jnt_pick.activated.connect(self.pick_number_tag)
        grid.addWidget(self.jnt_pick, 3, 0, 1, 3)
        refresh = QPushButton("↻")
        refresh.setToolTip("Read the number tags from SDS-Manager again")
        refresh.clicked.connect(self.fill_number_tags)
        grid.addWidget(refresh, 3, 3)
        self.fill_number_tags()
        layout.addWidget(box)

    def fill_number_tags(self):
        choices = manager_tag_choices(load_manager_keys())
        self.jnt_pick.clear()
        if not choices:
            self.jnt_pick.addItem("No number tags in SDS-Manager's configuration yet (Favorites → Keys & Tags)", None)
            return
        self.jnt_pick.addItem(f"Choose one of {len(choices)} tagged items…", None)
        for label, tags in choices:
            self.jnt_pick.addItem(label, tags)

    def pick_number_tag(self, index):
        tags = self.jnt_pick.itemData(index)
        if not tags:
            return
        for spin, value in zip(self.jnt_boxes, tags):
            spin.setValue(-1 if value is None else int(value))

    JNT_HINT = ("A number tag is a number you give a favorites list, system or channel so you can jump "
                "straight to it. It is not the quick key: quick key 1 and number tag 1 are separate "
                "settings, and most lists have no number tags until you set them (SDS-Manager: "
                "Favorites List Settings for lists, the Number Tag column for channels; or Sentinel). "
                "Quick keys turn scanning on and off: QUICK KEYS….")

    def open_quick_keys(self):
        self.open_scanner_tools()
        tools = self.scanner_tools
        if tools is not None:
            for i in range(tools.tabs.count()):
                if tools.tabs.tabText(i) == "Quick Keys":
                    tools.tabs.setCurrentIndex(i)
                    break

    def jump_number_tag(self):
        values = [b.value() for b in self.jnt_boxes]
        if all(v < 0 for v in values):
            set_text(self.jnt_label, "Enter at least one number tag.")
            return
        for i, v in enumerate(values):
            self.settings.setValue(f"jnt/{i}", v)
        fields = ["" if v < 0 else str(v) for v in values]
        command = "JNT," + ",".join(fields)
        if self.queue(command):
            self.pending_jnt = "/".join(f or "—" for f in fields)
            set_text(self.jnt_label, f"Going to number tag {self.pending_jnt}…")
            self.command_reply("QUEUED: " + command)

    def handle_jnt_reply(self, body):
        tags = getattr(self, "pending_jnt", None) or "?"
        self.pending_jnt = None
        if body.strip() == "OK":
            set_text(self.jnt_label, f"✓ Scanner went to number tag {tags}.")
        else:
            set_text(self.jnt_label, f"The scanner has nothing with number tag {tags} ({body.strip()}). "
                "Number tags aren't quick keys: favorites list quick key 1 is not number tag 1. Give the "
                "list, system and channel number tags first (SDS-Manager or Sentinel); the list must be "
                "monitored, and the scanner not in a menu. To turn lists on or off, use QUICK KEYS….")

    # ---- Status bar indicators --------------------------------------------
    SIGNAL_BARS = ["▁", "▁▂", "▁▂▃", "▁▂▃▄", "▁▂▃▄▅"]

    def update_status_flags(self, prop, ifx):
        """Status bar indicators from the GSI report (spec V2.00). Each one is a
        link: clicking it opens a menu of related actions."""
        chips = []      # (id, text, colour, tooltip)
        if prop is not None:
            sig = self.attr(prop, "Sig", "")
            if sig.isdigit():
                level = min(4, int(sig))
                chips.append(("sig", f"{self.SIGNAL_BARS[level]} {level}/4",
                              "#7ee3a5" if level >= 3 else "#e6a65a" if level >= 1 else "#8392a6",
                              f"Signal: {level} of 4 bars (as on the scanner's display)"))
            mute = self.attr(prop, "Mute", "")
            if mute in ("Mute", "Unmute"):
                open_ = mute == "Unmute"
                chips.append(("sql", "🔊 OPEN" if open_ else "🔈 closed",
                              "#52dc95" if open_ else "#8392a6",
                              "Squelch open: audio is playing" if open_
                              else "Squelch closed (muted)"))
            vol, sql = self.attr(prop, "VOL", ""), self.attr(prop, "SQL", "")
            if vol.isdigit() and sql.isdigit():
                chips.append(("volsql", f"VOL {vol} • SQL {sql}", "#c9d6e6",
                              "Volume and squelch levels"))
            direction = self.attr(prop, "Dir", "")
            if direction in ("Up", "Down"):
                chips.append(("dir", "▲" if direction == "Up" else "▼", "#c9d6e6",
                              f"Scan direction: {direction.lower()}"))
            att = self.attr(prop, "Att", "Off")
            if att == "G-Att":
                chips.append(("att", "G-ATT", "#e6a65a", "Global attenuator on"))
            elif att == "On":
                chips.append(("att", "ATT", "#e6a65a", "Attenuator on"))
            else:
                chips.append(("att", "att", "#5d6878", "Attenuator off"))
            if self.attr(prop, "KeyLock", "Off") == "On":
                chips.append(("lock", "🔒 KEY LOCK", "#e6a65a", "The scanner's keys are locked"))
            if self.attr(prop, "F", "Off") == "On":
                chips.append(("func", "FUNC", "#b48cf0", "FUNC is active on the scanner"))
            p25 = self.attr(prop, "P25Status", "None")
            if p25 not in ("None", "—", ""):
                chips.append(("p25", p25, "#8bd6f2",
                              f"Decoding: {P25_STATUS_NAMES.get(p25, p25)}"))
        if ifx == "On":
            chips.append(("ifx", "IFX", "#8bd6f2", "IF Exchange is on for this channel"))
        if prop is not None:
            led = self.attr(prop, "A_Led", "Off")
            if led not in ("Off", "—", ""):
                chips.append(("alert", "● ALERT", LED_HEX.get(led, "#fdfdfd"),
                              f"Alert LED: {led}"))
            backlight = self.attr(prop, "Backlight", "")
            if backlight.isdigit():
                chips.append(("light", f"☀ {backlight}%", "#c9d6e6", "Backlight level"))
        html = "&nbsp;&nbsp;".join(
            f'<a href="{cid}" style="color:{colour};font-weight:700;'
            f'text-decoration:none;">{text}</a>'
            for cid, text, colour, _tip in chips)
        if html != self.flags_html:
            self.flags_html = html
            self.flag_tips = {cid: tip for cid, _t, _c, tip in chips}
            set_text(self.flags_label, html)
            self.flags_label.setToolTip(
                "\n".join(tip for _i, _t, _c, tip in chips)
                + ("\n\nClick an indicator for related actions." if chips else ""))

    def flag_clicked(self, cid):
        """Menu of actions for a clicked status-bar indicator."""
        menu = QMenu(self)
        connected = self.connected
        tip = getattr(self, "flag_tips", {}).get(cid, "")
        if tip:
            menu.addAction("ⓘ " + tip).setEnabled(False)
            menu.addSeparator()

        def add(label, slot, needs_connection=True, tooltip=None):
            action = menu.addAction(label, slot)
            action.setEnabled(connected or not needs_connection)
            if tooltip:
                action.setToolTip(tooltip)
            return action

        def show_dock(index):
            self.docks[index].show()
            self.docks[index].raise_()

        if cid in ("sig", "p25"):
            add("Analyze → System Status…",
                lambda: self.open_analyze("SYSTEM_STATUS"), False)
            add("Analyze → Current Activity…",
                lambda: self.open_analyze("CURRENT_ACTIVITY"), False)
        elif cid in ("sql", "volsql"):
            add("Volume and squelch controls (SCANNER CONTROL)", lambda: show_dock(1), False)
        elif cid == "dir":
            add("Scan down (knob left)", lambda: self.send_key("<"))
            add("Scan up (knob right)", lambda: self.send_key(">"))
        elif cid == "att":
            add("Toggle attenuator (FUNC + 4)",
                lambda: self.send_key_sequence(("F", "4"), "Toggle attenuator (FUNC + 4)"))
            add("Toggle global attenuator (FUNC + hold 4)",
                lambda: self.send_function_long_press(
                    "4", "Toggle Global Attenuation (FUNC + hold 4)"))
        elif cid == "lock":
            menu.addAction("Unlock the keys on the scanner itself; remote commands "
                           "still work while locked.").setEnabled(False)
            add("Scanner Screen…", lambda: self.screen_mirror.open(), False)
        elif cid == "func":
            add("Cancel FUNC (press FUNC)", lambda: self.send_key("F"))
        elif cid == "ifx":
            add("Toggle IF Exchange (FUNC + 7, in hold)",
                lambda: self.send_key_sequence(("F", "7"), "Toggle IF Exchange (FUNC + 7)"))
        elif cid == "alert":
            add("Alerts (Scanner Tools)…", self.open_alerts_tab, False)
            add("Scanner Screen…", lambda: self.screen_mirror.open(), False)
        elif cid == "light":
            add("Backlight key", lambda: self.send_key("V"))
            add("Dimmer settings (FUNC + 5, in hold)",
                lambda: self.send_key_sequence(("F", "5"), "Open dimmer settings (FUNC + 5)"))
        if menu.isEmpty():
            return
        menu.exec(QCursor.pos())

    def open_alerts_tab(self):
        self.open_scanner_tools()
        tools = self.scanner_tools
        if tools is not None and getattr(self, "alerts_panel", None) is not None:
            tools.tabs.setCurrentWidget(self.alerts_panel)

    # ---- Theme (v1.1.40) -----------------------------------------------------
    def build_theme_menu(self, menu):
        self.theme_actions = {}
        for group, title, options in (
                ("mode", "Mode", [(k, v) for k, v in THEME_MODES.items()]),
                ("accent", "Accent", [(k, v[0]) for k, v in THEME_ACCENTS.items()]),
                ("size", "Text size", [(k, v[0]) for k, v in TEXT_SIZES.items()])):
            heading = menu.addAction(title)
            heading.setEnabled(False)
            for key, label in options:
                action = menu.addAction(label, lambda checked=False, g=group, k=key:
                                        self.set_theme_option(g, k))
                action.setCheckable(True)
                self.theme_actions[(group, key)] = action
            menu.addSeparator()
        menu.aboutToShow.connect(self.update_theme_menu)
        self.update_theme_menu()
        # System mode: notice KDE switching between light and dark schemes.
        self.theme_watch = QTimer(self)
        self.theme_watch.setInterval(4000)
        self.theme_watch.timeout.connect(self.check_system_theme)
        self.theme_watch.start()

    def check_system_theme(self):
        if THEME.choice != "system":
            return
        dark = system_is_dark()
        if dark != (THEME.mode == "dark"):
            apply_theme(Theme("system", THEME.accent, THEME.size, dark))
            self.statusBar().showMessage(
                f"Theme: following KDE — {'dark' if dark else 'light'}", 6000)

    def update_theme_menu(self):
        current = {"mode": THEME.choice, "accent": THEME.accent, "size": THEME.size}
        for (group, key), action in self.theme_actions.items():
            action.setChecked(current[group] == key)
            if group == "accent":
                action.setEnabled(THEME.mode != "night")
                action.setToolTip("Night mode is all red" if THEME.mode == "night" else "")

    def set_theme_option(self, group, key):
        values = {"mode": THEME.choice, "accent": THEME.accent, "size": THEME.size}
        values[group] = key
        self.settings.setValue(f"theme/{group}", key)
        apply_theme(Theme(values["mode"], values["accent"], values["size"], system_is_dark()))
        self.update_theme_menu()
        name = THEME_MODES[THEME.choice]
        if THEME.choice == "system":
            name += f" — {'dark' if THEME.mode == 'dark' else 'light'} now"
        accent = "" if THEME.mode == "night" else f", {THEME_ACCENTS[THEME.accent][0]} accent"
        self.statusBar().showMessage(
            f"Theme: {name}{accent}, {TEXT_SIZES[THEME.size][0].lower()} text", 6000)

    def changeEvent(self, event):
        # KDE changing between light and dark colour schemes (System mode).
        if (event.type() == QEvent.Type.ApplicationPaletteChange
                and THEME.choice == "system"):
            QTimer.singleShot(0, self.check_system_theme)
        super().changeEvent(event)

    def open_analyze(self, mode=None):
        self.analyze.open(mode)


    # ---- Connection management ----------------------------------------------
    def auto_reconnect_toggled(self, on):
        self.settings.setValue("auto_reconnect", on)
        if not on and self.reconnect_timer.isActive():
            self.cancel_reconnect("Automatic reconnect turned off.")

    def update_connect_button(self):
        if self.thread and self.thread.isRunning():
            set_text(self.connect_btn, "DISCONNECT")
        elif self.reconnect_timer.isActive():
            set_text(self.connect_btn, "STOP RECONNECTING")
        else:
            set_text(self.connect_btn, "CONNECT")

    def cancel_reconnect(self, why):
        self.reconnect_timer.stop()
        self.reconnect_attempts = 0
        set_text(self.status, why)
        set_css(self.status, "color:#ed8b8b;")
        self.update_connect_button()

    def schedule_reconnect(self):
        self.reconnect_attempts += 1
        delay = min(30, 5 * self.reconnect_attempts)     # 5, 10, 15 … 30 s
        self.reconnect_timer.start(delay * 1000)
        set_text(self.status, f"RECONNECTING in {delay} s (attempt {self.reconnect_attempts})…")
        set_css(self.status, "color:#e6a65a;")
        self.statusBar().showMessage(
            "Scanner disconnected; reconnecting automatically. "
            "Press STOP RECONNECTING to stop.", 8000)
        self.update_connect_button()

    def check_responding(self):
        """Every 2 s: warn (and reconnect if allowed) when the scanner goes quiet."""
        if not (self.connected and self.thread and self.thread.isRunning()):
            return
        quiet = time.monotonic() - self.last_rx
        if quiet < 15:
            self.stall_warned = False
            return
        if self.auto_reconnect_box.isChecked():
            self.statusBar().showMessage(
                f"The scanner hasn't answered for {quiet:.0f} s; reconnecting.", 10000)
            self.user_stopped = False
            self.release_diagnostic_key()
            self.thread.stop()
        elif not self.stall_warned:
            self.stall_warned = True
            self.statusBar().showMessage(
                f"The scanner hasn't answered for {quiet:.0f} s. Check the cable and "
                "that the scanner is on.", 15000)

    # ---- PC audio capture -----------------------------------------------
    def build_pc_audio(self, layout):
        group = QGroupBox("PC AUDIO CAPTURE • one MP3 per transmission")
        grid = QGridLayout(group)
        self.pc_audio_enable = QCheckBox("Record each transmission")
        self.pc_audio_enable.setToolTip(
            "Records the PC sound input below while the scanner reports a reception, "
            "and saves each one as an MP3 with tags, plus a row in the day's CSV index.")
        self.pc_audio_device = QComboBox()
        self.pc_audio_device.setToolTip("The sound input the scanner's headphone jack is "
                                        "connected to (line-in or USB sound card)")
        refresh = QPushButton("↻")
        refresh.setToolTip("Refresh the list of sound inputs")
        refresh.setMaximumWidth(36)
        self.pc_audio_level = QProgressBar()
        self.pc_audio_level.setRange(0, 60)
        self.pc_audio_level.setValue(0)
        self.pc_audio_level.setFormat("Input level: —")
        self.pc_audio_level.setToolTip("Peak level of the sound input. Aim for -12 to -3 dBFS "
                                       "during speech; set the scanner volume to suit.")
        settings_btn = QPushButton("SETTINGS…")
        settings_btn.clicked.connect(self.pc_audio_settings)
        recordings_btn = QPushButton("RECORDINGS…")
        recordings_btn.clicked.connect(self.open_audio_recordings)
        self.pc_audio_status = make_label("")
        self.pc_audio_status.setWordWrap(True)
        grid.addWidget(self.pc_audio_enable, 0, 0, 1, 3)
        grid.addWidget(make_label("INPUT"), 1, 0)
        grid.addWidget(self.pc_audio_device, 1, 1)
        grid.addWidget(refresh, 1, 2)
        grid.addWidget(self.pc_audio_level, 2, 0, 1, 3)
        buttons = QHBoxLayout()
        buttons.addWidget(settings_btn)
        buttons.addWidget(recordings_btn)
        grid.addLayout(buttons, 3, 0, 1, 3)
        grid.addWidget(self.pc_audio_status, 4, 0, 1, 3)
        grid.setColumnStretch(1, 1)
        layout.addWidget(group)

        self.pc_audio_indicator = make_label("● PC AUDIO")
        set_css(self.pc_audio_indicator, "color:#52dc95; font-weight:700; padding:0 8px;")
        self.pc_audio_indicator.setToolTip("Recording this transmission from the PC sound input")
        self.pc_audio_indicator.setVisible(False)
        self.statusBar().addPermanentWidget(self.pc_audio_indicator)
        self.audio_devices = []

        problem = None
        if self.audio is None:
            problem = ("Needs Qt Multimedia: sudo apt install python3-pyqt6.qtmultimedia, "
                       "then restart SDS100 Monitor.")
        elif shutil.which("ffmpeg") is None:
            problem = "ffmpeg was not found; it is needed to write MP3 files (sudo apt install ffmpeg)."
        if problem:
            for w in (self.pc_audio_enable, self.pc_audio_device, refresh, settings_btn):
                w.setEnabled(False)
            set_text(self.pc_audio_status, problem)
            set_css(self.pc_audio_status, "color:#ff8a65;")
            return
        self.media_devices = QMediaDevices(self)
        self.media_devices.audioInputsChanged.connect(self.refresh_audio_inputs)
        refresh.clicked.connect(lambda: self.refresh_audio_inputs())
        self.refresh_audio_inputs(saved=str(self.settings.value("pcaudio/device", "")))
        self.pc_audio_device.currentIndexChanged.connect(self.audio_input_changed)
        self.pc_audio_enable.toggled.connect(self.toggle_pc_audio)
        self.audio.level.connect(self.show_audio_level)
        self.audio.capturing.connect(self.pc_audio_indicator.setVisible)
        self.audio.saved.connect(self.audio_saved)
        self.audio.skipped.connect(lambda text: self.set_audio_status(text))
        self.audio.failed.connect(self.audio_failed)
        self.set_audio_status("Off. Tick the box to record each transmission.")
        if str(self.settings.value("pcaudio/enabled", "false")).lower() == "true":
            self.pc_audio_enable.setChecked(True)

    def refresh_audio_inputs(self, saved=None):
        current = saved or self.pc_audio_device.currentText()
        self.audio_devices = list(QMediaDevices.audioInputs())
        self.pc_audio_device.blockSignals(True)
        self.pc_audio_device.clear()
        for device in self.audio_devices:
            self.pc_audio_device.addItem(device.description())
        names = [d.description() for d in self.audio_devices]
        if current in names:
            self.pc_audio_device.setCurrentIndex(names.index(current))
        else:
            default = QMediaDevices.defaultAudioInput()
            ids = [d.id() for d in self.audio_devices]
            if default.id() in ids:
                self.pc_audio_device.setCurrentIndex(ids.index(default.id()))
        self.pc_audio_device.blockSignals(False)
        if not self.audio_devices:
            self.set_audio_status("No sound inputs found. Connect the scanner's headphone "
                                  "jack to line-in or a USB sound card, then press ↻.", error=True)
        elif saved is None and self.pc_audio_enable.isChecked() and current not in names:
            self.audio_input_changed()

    def audio_input_changed(self, _index=None):
        if self.pc_audio_enable.isChecked():
            self.toggle_pc_audio(True)

    def toggle_pc_audio(self, enabled):
        if not enabled:
            self.audio.stop()
            self.pc_audio_level.setValue(0)
            self.pc_audio_level.setFormat("Input level: —")
            self.set_audio_status("Off. Tick the box to record each transmission.")
            return
        index = self.pc_audio_device.currentIndex()
        if index < 0 or index >= len(self.audio_devices):
            self.set_audio_status("Choose a sound input first.", error=True)
            self.pc_audio_enable.setChecked(False)
            return
        device = self.audio_devices[index]
        if self.audio.start(device):
            mode = "mono" if self.audio.mono else f"{self.audio.channels} ch"
            self.set_audio_status(
                f"Listening on {device.description()} ({self.audio.rate} Hz, saving "
                f"{self.audio.bitrate} {mode} MP3). Waiting for a reception…"
                + ("" if getattr(self, "connected", False) else " Connect to the scanner to start recording."))
        else:
            self.pc_audio_enable.setChecked(False)

    def show_audio_level(self, dbfs):
        self.pc_audio_level.setValue(int(max(0, min(60, dbfs + 60))))
        self.pc_audio_level.setFormat("Input level: —" if dbfs <= -90
                                      else f"Input level: {dbfs:.0f} dBFS")

    def set_audio_status(self, text, error=False):
        set_text(self.pc_audio_status, text)
        set_css(self.pc_audio_status, "color:#ff8a65;" if error else "color:#a5bdd2;")

    def audio_saved(self, path, row):
        self.set_audio_status(f"Saved {row[0][11:]} {row[5]} ({row[12]} s): {Path(path).name}")
        if self.audio_recordings is not None:
            self.audio_recordings.add_saved(row)
        if self.transcription_window is not None:
            self.transcription_window.new_recording(row)
        self.transcriber.new_recording(row)
        if self.transcription_window is not None:
            self.transcription_window.update_status()
        self.rdio.call_saved(path, row)

    # ---- Transcription (v1.1.28) ------------------------------------------
    # ---- Analysis windows (v1.1.31) ---------------------------------------
    def open_analysis(self, attr, cls):
        window = getattr(self, attr)
        if window is None:
            window = cls(self)
            setattr(self, attr, window)
        window.open()

    def update_gps_label(self):
        text, colour, tip = self.gps.indicator()
        set_text(self.gps_label, f'<a href="gps" style="color:{colour};font-weight:700;'
                               f'text-decoration:none;">{text}</a>' if text else "")
        self.gps_label.setToolTip(tip)

    def open_search(self, text=None):
        if self.search_window is None:
            self.search_window = GlobalSearchWindow(self)
        self.search_window.open(text)

    def open_transcription(self):
        if self.transcription_window is None:
            self.transcription_window = TranscriptionWindow(self)
        self.transcription_window.open()

    def transcript_ready(self, row):
        """A call was transcribed: check keyword (Transcript) alerts and
        look for a call sign that names the radio."""
        self.unit_suggester.transcript_added(row)
        self.places_finder.transcript_added(row)
        try:
            if self.adsb.transcript_added(row) and self.transcription_window is not None:
                self.transcription_window.heard_changed(row)
        except Exception as exc:              # aircraft matching must never stop transcription
            self.statusBar().showMessage(f"Aircraft matching: {exc}", 5000)
        text = row[8]
        if not text:
            return
        values = {"System": row[1], "Department": row[2], "Channel": row[3],
                  "Talkgroup": row[4], "Unit ID": row[5], "Transcript": text}
        self.check_alerts(values, transcript=True)

    def audio_failed(self, text):
        self.set_audio_status(text, error=True)
        self.statusBar().showMessage(text, 10000)

    def pc_audio_settings(self):
        dialog = AudioSettingsDialog(self.audio, self)
        if dialog.exec():
            dialog.apply(self.audio)
            self.save_settings()
            if self.pc_audio_enable.isChecked() and self.audio.current is None:
                self.toggle_pc_audio(True)      # show the new bitrate/mode

    def open_audio_recordings(self):
        window = self.open_window("audio_recordings", lambda: AudioRecordings(self))
        window.reload()

    # ---- Audio, recording, clock, tuning and battery ---------------------
    # Commands from Remote Command Specification V2.00: VOL, SQL, URC, DTM,
    # QSH and GCS.
    URC_ERRORS = {
        "0001": "file access error (check the SD card)",
        "0002": "battery too low to record",
        "0003": "recording session limit reached",
        "0004": "the scanner's clock was lost; set the clock, then try again",
    }
    CHARGE_STATES = {
        "0": "no external power", "1": "battery gauge starting",
        "2": "battery temperature abnormal", "3": "power supply abnormal",
        "4": "fully charged", "5": "recharging", "6": "charging",
    }
    GCS_PATTERN = re.compile(
        r"GCS,CST=(\d+),VOLT=(\d+)mV:(\d+)%,CURR=([+-]?\d+)mA,TEMP=\s*([-+]?[\d.]+)C")

    def build_scanner_settings(self, layout):
        self.settings_controls = []
        self.recording = None
        self.clock_step = None
        self.pending_qsh = None
        self.qsh_verify = None
        self.audio_pending = {}
        self.audio_hold_until = 0.0
        self.low_battery_warned = False

        audio = QGroupBox("AUDIO")
        audio_grid = QGridLayout(audio)
        self.audio_sliders, self.audio_labels = {}, {}
        for row, (name, cmd) in enumerate((("Volume", "VOL"), ("Squelch", "SQL"))):
            audio_grid.addWidget(make_label(name.upper()), row, 0)
            slider = QSlider(Qt.Orientation.Horizontal)
            slider.setRange(0, 15)          # SDS100 range (SDS200: set on connect)
            slider.setPageStep(1)
            slider.setTickPosition(QSlider.TickPosition.TicksBelow)
            slider.setTickInterval(1)
            slider.setEnabled(False)
            slider.valueChanged.connect(lambda value, c=cmd: self.audio_changed(c, value))
            value_label = make_label("—")
            value_label.setMinimumWidth(30)
            audio_grid.addWidget(slider, row, 1)
            audio_grid.addWidget(value_label, row, 2)
            self.audio_sliders[cmd], self.audio_labels[cmd] = slider, value_label
            self.settings_controls.append(slider)
        audio_grid.setColumnStretch(1, 1)
        # Send after the slider stops moving, not on every step.
        self.audio_timer = QTimer(self)
        self.audio_timer.setSingleShot(True)
        self.audio_timer.setInterval(300)
        self.audio_timer.timeout.connect(self.send_audio)
        layout.addWidget(audio)

        rec = QGroupBox("RECORDING")
        rec_row = QHBoxLayout(rec)
        self.rec_button = QPushButton("● START RECORDING")
        set_css(self.rec_button, "QPushButton {background:#a83232; color:white; font-weight:700; padding:9px; border-radius:6px;}"
            "QPushButton:disabled {background:#414750; color:#a4a9b0;}")
        self.rec_button.setEnabled(False)
        self.rec_button.clicked.connect(self.toggle_recording)
        self.settings_controls.append(self.rec_button)
        rec_row.addWidget(self.rec_button)
        self.rec_state_label = make_label("Recording: —")
        self.rec_state_label.setWordWrap(True)
        rec_row.addWidget(self.rec_state_label, 1)
        layout.addWidget(rec)
        self.build_pc_audio(layout)

        clock = QGroupBox("SCANNER CLOCK")
        clock_grid = QGridLayout(clock)
        read_btn = QPushButton("READ CLOCK")
        read_btn.clicked.connect(self.read_clock)
        sync_btn = QPushButton("SET CLOCK FROM PC")
        sync_btn.setToolTip("Sets the scanner's date and time to this computer's, keeping "
                            "the scanner's daylight-saving setting, then reads it back to check")
        sync_btn.clicked.connect(self.sync_clock)
        for b in (read_btn, sync_btn):
            b.setEnabled(False)
            self.settings_controls.append(b)
        clock_grid.addWidget(read_btn, 0, 0)
        clock_grid.addWidget(sync_btn, 0, 1)
        self.clock_label = make_label("Scanner clock: —")
        self.clock_label.setWordWrap(True)
        clock_grid.addWidget(self.clock_label, 1, 0, 1, 2)
        layout.addWidget(clock)

        tune = QGroupBox("TUNE TO FREQUENCY • Quick Search Hold")
        tune_grid = QGridLayout(tune)
        self.tune_entry = QLineEdit()
        self.tune_entry.setPlaceholderText("Frequency in MHz, e.g. 162.5500")
        self.tune_entry.returnPressed.connect(lambda: self.tune_frequency())
        self.tune_entry.setEnabled(False)
        tune_btn = QPushButton("HOLD ON FREQUENCY")
        tune_btn.clicked.connect(lambda: self.tune_frequency())
        tune_btn.setEnabled(False)
        self.settings_controls += [self.tune_entry, tune_btn]
        tune_grid.addWidget(self.tune_entry, 0, 0)
        tune_grid.addWidget(tune_btn, 0, 1)
        tune_note = make_label("Also: right-click a reception in history → Hold on This Frequency. "
                           "The scanner ignores this while it is in a menu.")
        tune_note.setWordWrap(True)
        set_css(tune_note, "color:#a5bdd2;")
        tune_grid.addWidget(tune_note, 1, 0, 1, 2)
        layout.addWidget(tune)

        self.flags_label = make_label("")
        self.flags_label.setTextFormat(Qt.TextFormat.RichText)
        self.flags_label.linkActivated.connect(self.flag_clicked)
        set_css(self.flags_label, "padding:0 8px;")
        self.statusBar().addPermanentWidget(self.flags_label)
        self.rec_indicator = make_label("● REC")
        set_css(self.rec_indicator, "color:#ff5c5c; font-weight:700; padding:0 8px;")
        self.rec_indicator.setVisible(False)
        self.statusBar().addPermanentWidget(self.rec_indicator)
        self.update_label = make_label("")
        set_css(self.update_label, "padding:0 8px;color:#a5bdd2;")
        self.statusBar().addPermanentWidget(self.update_label)
        self.battery_label = make_label("Battery: —")
        set_css(self.battery_label, "padding:0 8px;")
        self.statusBar().addPermanentWidget(self.battery_label)
        self.battery_timer = QTimer(self)
        self.battery_timer.setInterval(30000)
        self.battery_timer.timeout.connect(self.poll_battery)

    def set_settings_enabled(self, enabled):
        for widget in self.settings_controls:
            widget.setEnabled(enabled)
        if enabled:
            self.gcs_failures, self.gcs_waiting = 0, False
            self.screen_battery = None
            QTimer.singleShot(1500, self.poll_battery)
            self.battery_timer.start()
        else:
            self.battery_timer.stop()
            set_text(self.battery_label, "Battery: —")
            set_css(self.battery_label, "padding:0 8px;")
            self.rec_indicator.setVisible(False)
            self.recording = None
            set_text(self.rec_state_label, "Recording: —")
            self.clock_step = self.pending_qsh = self.qsh_verify = None

    def queue(self, command):
        if self.thread and self.thread.isRunning():
            self.thread.send_command(command)
            return True
        return False

    # Audio --------------------------------------------------------------
    def audio_changed(self, cmd, value):
        set_text(self.audio_labels[cmd], str(value))
        self.audio_pending[cmd] = value
        # Don't let status updates move the slider back while it is in use.
        self.audio_hold_until = time.monotonic() + 2.5
        self.audio_timer.start()

    def send_audio(self):
        for cmd, value in self.audio_pending.items():
            if self.queue(f"{cmd},{value}"):
                self.command_reply(f"QUEUED: {cmd},{value}")
        self.audio_pending.clear()

    def sync_audio(self, prop):
        if prop is None or time.monotonic() < self.audio_hold_until:
            return
        for cmd in ("VOL", "SQL"):
            raw = prop.attrib.get(cmd, "").strip()
            if raw.isdigit():
                slider = self.audio_sliders[cmd]
                slider.blockSignals(True)
                slider.setValue(int(raw))
                slider.blockSignals(False)
                set_text(self.audio_labels[cmd], raw)

    # Recording ------------------------------------------------------------
    def toggle_recording(self):
        start = not self.recording
        if self.queue(f"URC,{1 if start else 0}"):
            set_text(self.rec_state_label, "Starting recording…" if start else "Stopping recording…")

    def sync_recording(self, prop):
        if prop is None:
            return
        state = prop.attrib.get("Rec", "").strip().lower()
        if state not in ("on", "off"):
            return
        recording = state == "on"
        if recording == self.recording:
            return
        self.recording = recording
        self.rec_indicator.setVisible(recording)
        set_text(self.rec_button, "■ STOP RECORDING" if recording else "● START RECORDING")
        set_text(self.rec_state_label, "Recording: ON (saving to the scanner's SD card)"
                                     if recording else "Recording: off")

    # Clock ---------------------------------------------------------------
    def read_clock(self):
        if self.queue("DTM"):
            self.clock_step = "read"
            set_text(self.clock_label, "Reading scanner clock…")

    def sync_clock(self):
        # Read first, so the scanner's own daylight-saving setting is kept.
        if self.queue("DTM"):
            self.clock_step = "sync-read"
            set_text(self.clock_label, "Reading scanner clock before setting it…")

    def handle_clock_reply(self, body):
        if body == "OK":
            if self.clock_step == "sync-set":
                self.clock_step = "verify"
                self.queue("DTM")
            return
        # DTM,[DST],[YYYY],[MM],[DD],[hh],[mm],[ss],[RTC Status]
        parts = [p.strip() for p in body.split(",")]
        if len(parts) < 7 or not all(p.lstrip("-").isdigit() for p in parts[:7]):
            set_text(self.clock_label, f"Scanner clock: the scanner replied DTM,{body}")
            self.clock_step = None
            return
        dst = parts[0]
        try:
            scanner_time = datetime(*(int(p) for p in parts[1:7]))
        except ValueError:
            set_text(self.clock_label, f"Scanner clock: unreadable reply DTM,{body}")
            self.clock_step = None
            return
        rtc_ok = len(parts) < 8 or parts[7] == "1"
        if self.clock_step == "sync-read":
            now = datetime.now()
            self.queue(f"DTM,{dst},{now:%Y},{now:%m},{now:%d},{now:%H},{now:%M},{now:%S}")
            self.clock_step = "sync-set"
            set_text(self.clock_label, "Setting scanner clock…")
            return
        diff = (scanner_time - datetime.now()).total_seconds()
        text = (f"Scanner clock: {scanner_time:%Y-%m-%d %H:%M:%S} • "
                f"difference from PC: {diff:+.0f} s • daylight-saving setting: {dst}")
        if not rtc_ok:
            text += " • ⚠ scanner reports its clock is not valid (RTC NG)"
        if self.clock_step == "verify":
            if abs(abs(diff) - 3600) < 120:
                text += ("\n⚠ Exactly about one hour off after setting. The scanner may be "
                         "applying daylight saving on top of the time sent. Please report this.")
            elif abs(diff) <= 5:
                text = "✓ Scanner clock set. " + text
        set_text(self.clock_label, text)
        self.clock_step = None

    # Quick Search Hold ------------------------------------------------------
    QSH_FORMATS = ("100hz", "mhz")

    @staticmethod
    def qsh_command(mhz, fmt):
        # The spec does not define QSH's frequency format. "100hz" is the
        # BCD536HP/436HP convention the SDS spec was derived from (8 digits in
        # 100 Hz units, 162.4 MHz -> 01624000); "mhz" matches GSI (162.400000).
        return "QSH," + (f"{round(mhz * 10000):08d}" if fmt == "100hz" else f"{mhz:.6f}")

    def tune_frequency(self, mhz=None):
        if mhz is None:
            try:
                mhz = self.validate_mhz(self.tune_entry.text())
            except ValueError as exc:
                QMessageBox.warning(self, "Tune to frequency", str(exc))
                return
        preferred = str(self.settings.value("qsh_format", "100hz"))
        if preferred not in self.QSH_FORMATS:
            preferred = "100hz"
        order = [preferred] + [f for f in self.QSH_FORMATS if f != preferred]
        self.pending_qsh = {"mhz": mhz, "formats": order[1:], "format": order[0]}
        if self.queue(self.qsh_command(mhz, order[0])):
            self.command_reply(f"QUEUED: Quick Search Hold on {mhz:.4f} MHz")

    def handle_qsh_reply(self, body):
        pending = self.pending_qsh
        if pending is None:
            return False
        if body == "OK":
            self.pending_qsh = None
            self.qsh_verify = {"mhz": pending["mhz"], "format": pending["format"],
                               "deadline": time.monotonic() + 4}
            self.command_reply(f"Quick Search Hold accepted: {pending['mhz']:.4f} MHz — checking…")
        elif pending["formats"]:
            fmt = pending["formats"].pop(0)
            pending["format"] = fmt
            self.queue(self.qsh_command(pending["mhz"], fmt))
            self.command_reply("Scanner rejected the first frequency format; trying the other one…")
        else:
            self.pending_qsh = None
            self.command_reply(f"Quick Search Hold rejected (QSH,{body}). The scanner does not "
                               "accept it in a menu, during Direct Entry or Quick Save.")
        return True

    def check_qsh(self, frequency):
        """Confirm from GSI that the scanner really went to the requested frequency."""
        verify = self.qsh_verify
        if verify is None:
            return
        reported = parse_mhz(frequency)
        if reported is not None and abs(reported - verify["mhz"]) < 0.0005:
            self.settings.setValue("qsh_format", verify["format"])
            self.command_reply(f"✓ Holding on {reported:.4f} MHz")
            self.qsh_verify = None
        elif time.monotonic() > verify["deadline"]:
            self.qsh_verify = None
            if reported is not None:
                other = [f for f in self.QSH_FORMATS if f != verify["format"]][0]
                self.settings.setValue("qsh_format", other)
                self.command_reply(
                    f"⚠ Scanner reports {reported:.4f} MHz, not {verify['mhz']:.4f} MHz. "
                    "Switched to the other frequency format; please try again.")
            else:
                self.command_reply("Quick Search Hold accepted, but the scanner's frequency "
                                   "could not be confirmed.")

    # Battery ---------------------------------------------------------------
    # The SDS100 (firmware 1.26.01) answers GCS with ERR and has no Battery field in
    # GSI, but its own screen shows the battery voltage ("Batt:4.21V") in the
    # system information lines. So once GCS is refused, the voltage is read from
    # the screen text (GST) every 30 s, or from the Scanner Screen's own polling.
    BATT_SCREEN_PATTERN = re.compile(r"Batt\s*:\s*(\d+(?:\.\d+)?)\s*V", re.I)
    # Resting voltage → charge for a single Li-ion cell (approximate).
    LIION_CURVE = [(4.20, 100), (4.10, 90), (4.00, 79), (3.90, 64), (3.80, 47),
                   (3.75, 37), (3.70, 26), (3.65, 17), (3.60, 10), (3.50, 4), (3.40, 0)]

    @classmethod
    def liion_percent(cls, volts):
        curve = cls.LIION_CURVE
        if volts >= curve[0][0]:
            return 100
        for (v1, p1), (v2, p2) in zip(curve, curve[1:]):
            if v2 <= volts <= v1:
                return round(p2 + (p1 - p2) * (volts - v2) / (v1 - v2))
        return 0

    def poll_battery(self):
        if not self.connected:
            return
        if getattr(self, "gcs_failures", 0) < 2:
            self.queue("GCS")
        elif not (self.thread and getattr(self.thread, "screen_enabled", False)):
            # The Scanner Screen isn't already reading the screen: ask once.
            self.queue("GST")

    def battery_from_screen(self, reply):
        """Battery voltage from the scanner's screen text, if it's shown."""
        if getattr(self, "gcs_failures", 0) < 2:
            return                       # GCS works and gives more detail
        match = self.BATT_SCREEN_PATTERN.search(reply)
        if not match:
            if getattr(self, "screen_battery", None) is None:
                set_text(self.battery_label, "Battery: —")
                self.battery_label.setToolTip(
                    "This scanner doesn't report its battery through remote commands. "
                    "The voltage is read from the scanner's screen (Batt:) when the "
                    "current display shows it, which it does on the trunked system "
                    "information view.")
            return
        volts = float(match.group(1))
        if not 2.5 <= volts <= 5.0:
            return
        self.screen_battery = (volts, datetime.now())
        pct = self.liion_percent(volts)
        set_text(self.battery_label, f"Battery {volts:.2f} V ≈ {pct}%")
        self.battery_label.setToolTip(
            f"{volts:.2f} V, read from the scanner's screen at "
            f"{self.screen_battery[1]:%H:%M:%S}.\n"
            "The SDS100 doesn't report its charge level through remote commands, so the "
            "percentage is an estimate from the voltage of a lithium-ion cell. It reads "
            "high while charging (the scanner charges over the USB cable).\n"
            "Updated every 30 s while the scanner's display shows Batt:.")
        low = pct <= 15
        set_css(self.battery_label, "padding:0 8px;" + ("color:#ff7b7b;font-weight:700;"
                                                        if low else ""))
        if low and not self.low_battery_warned:
            self.low_battery_warned = True
            self.statusBar().showMessage(f"Scanner battery low: {volts:.2f} V", 30000)
        elif pct > 20:
            self.low_battery_warned = False

    def handle_battery_reply(self, reply):
        match = self.GCS_PATTERN.search(reply)
        if not match:
            return
        cst, mv, pct, ma, temp = match.groups()
        pct = int(pct)
        state = self.CHARGE_STATES.get(cst, f"state {cst}")
        set_text(self.battery_label, f"Battery {pct}% • {state}")
        self.battery_label.setToolTip(
            f"{int(mv) / 1000:.2f} V • {int(ma):+d} mA • {float(temp):.1f} °C")
        low = pct <= 15 and cst not in ("4", "5", "6")
        set_css(self.battery_label, "padding:0 8px;" + ("color:#ff7b7b;font-weight:700;" if low or cst in ("2", "3") else ""))
        if low and not self.low_battery_warned:
            self.low_battery_warned = True
            self.statusBar().showMessage(f"Scanner battery low: {pct}%", 30000)
        elif pct > 20:
            self.low_battery_warned = False

    def route_reply(self, reply):
        """Handle replies for the features above. Returns True to keep the
        reply out of the command status line (background battery polling)."""
        if reply == "SENT: GCS":
            self.gcs_waiting = True
            return True
        if getattr(self, "gcs_waiting", False) and (
                reply.strip() == "REPLY: ERR" or reply.startswith("REPLY: GCS,")):
            # Only these can be the GCS answer; streamed Analyze lines and other
            # replies may arrive in between and are left alone.
            self.gcs_waiting = False
            if reply.strip() in ("REPLY: ERR", "REPLY: GCS,ERR", "REPLY: GCS,NG"):
                # Some SDS100 firmware doesn't support GCS (seen on v1.1.38: a bare
                # ERR every time, on USB power). Stop asking after two refusals.
                self.gcs_failures = getattr(self, "gcs_failures", 0) + 1
                if self.gcs_failures == 2:
                    # Fall back to the voltage the scanner shows on its screen.
                    set_text(self.battery_label, "Battery: reading…")
                    self.battery_label.setToolTip(
                        "The scanner answers the battery command (GCS) with ERR, so the "
                        "voltage is read from its screen instead.")
                    QTimer.singleShot(500, self.poll_battery)
                return True
            if reply.startswith("REPLY: GCS,"):
                self.gcs_failures = 0
                self.handle_battery_reply(reply)
                return True
        if reply.startswith("REPLY: GLT,") and not reply.startswith("REPLY: GLT,<XML>"):
            target = self.glt_target()      # GLT,NG / GLT,ERR for a list request
            if target is not None:
                target.handle_list_error(reply[len("REPLY: GLT,"):])
            return True
        if reply.startswith("SENT: GLT"):
            return True          # keep the main status line quiet
        if reply.startswith(("REPLY: GST,", "REPLY: STS,")):
            self.screen_mirror.handle(reply)
            self.battery_from_screen(reply)
            return True
        if reply in ("SENT: GST", "SENT: STS"):
            return True              # background battery reads stay out of the status line
        if reply.startswith("REPLY: JNT,"):
            self.handle_jnt_reply(reply[len("REPLY: JNT,"):])
            return True
        self.discovery.route(reply)
        self.custom_search.route(reply)
        if self.analyze.route(reply):
            return True
        if self.modes_window.route(reply):
            return True
        if self.screc_window.route(reply):
            return True
        if self.close_call.route(reply):
            return True
        if self.scanner_menu.route(reply):
            return True
        if self.gps.route(reply):
            return True
        if self.scanner_tools is not None and self.scanner_tools.route(reply):
            return True
        if reply == "SENT: GCS":
            return True
        if reply.startswith("REPLY: GCS,"):
            self.handle_battery_reply(reply)
            return True
        if reply.startswith("REPLY: DTM,") and self.clock_step:
            # Shown in the clock section instead of the status line.
            self.handle_clock_reply(reply[len("REPLY: DTM,"):])
            return True
        if reply.startswith("REPLY: QSH,"):
            # Handled replies get their own explanatory message.
            return self.handle_qsh_reply(reply[len("REPLY: QSH,"):])
        if reply.startswith("REPLY: URC,ERR"):
            code = reply.rsplit(",", 1)[-1].strip()
            message = self.URC_ERRORS.get(code, f"error {code}")
            set_text(self.rec_state_label, f"Recording not started: {message}")
        elif reply == "REPLY: URC,OK" and self.recording is None:
            set_text(self.rec_state_label, "Recording command accepted")
        return False

    def scanner_identity(self, reply):
        """Show the model and firmware replies to the MDL/VER sent on connect."""
        if reply.startswith("REPLY: MDL,"):
            model = reply[len("REPLY: MDL,"):].strip()
            self.scanner_model = model
            if model.upper().startswith("SDS200"):
                self.audio_sliders["VOL"].setMaximum(29)
                self.audio_sliders["SQL"].setMaximum(19)
            if model.upper().startswith("SDS100"):
                set_text(self.scanner_label, f"Scanner: {model}")
            else:
                set_text(self.scanner_label, f"Scanner: {model} (not an SDS100?)")
                self.statusBar().showMessage(
                    f"Connected device reports model '{model}'; this program is written for the SDS100.", 15000)
        elif reply.startswith("REPLY: VER,"):
            version = reply[len("REPLY: VER,"):].strip()
            set_text(self.scanner_label, f"Scanner: {getattr(self, 'scanner_model', 'SDS100')} • firmware {version}")

    def command_reply(self, reply):
        if reply.startswith("REPLY: "):
            self.last_rx = time.monotonic()
        if self.route_reply(reply):
            return
        if len(reply) > 160:
            reply = reply[:160] + "…"
        set_text(self.command_status, reply)
        set_text(self.keypad_feedback, reply)
        set_text(self.waterfall_feedback, reply)
        if ",NG" in reply or ",ERR" in reply:
            set_css(self.command_status, "color:#ff9e91;")
        elif ",OK" in reply:
            set_css(self.command_status, "color:#7ee3a5;")
        else:
            set_css(self.command_status, "color:#c9d6e6;")

    def control(self, action):
        if not self.thread or not self.thread.isRunning():
            return
        channel = getattr(self, "current_channel_index", None)
        kind = getattr(self, "current_channel_type", None)
        system = getattr(self, "current_system_index", None)
        dept = getattr(self, "current_dept_index", None)
        cmd = None
        # "avoid_now" / "unavoid_now" (macro keypad) skip the confirmation question.
        confirm = not action.endswith("_now")
        action = action.removesuffix("_now")
        if action == "scan":
            # Documented: 0xFFFFFFFF restarts scanning from the first channel.
            cmd = "JPM,SCN_MODE,4294967295"
        elif action == "system_hold" and system:
            cmd = f"HLD,SYS,{system},"
        elif action == "dept_hold" and dept:
            cmd = f"HLD,DEPT,{dept},"
        elif action == "channel_hold" and channel and kind:
            cmd = f"HLD,{kind},{channel},"
        elif action in ("previous", "next") and channel and kind:
            verb = "PRV" if action == "previous" else "NXT"
            cmd = f"{verb},{kind},{channel},,1"
        elif action == "avoid" and channel and kind:
            name = self.fields["Channel"].text()
            if confirm:
                reply = QMessageBox.question(
                    self, "Confirm temporary avoid",
                    f"Temporarily avoid the currently displayed channel?\n\n{name}"
                )
                if reply != QMessageBox.StandardButton.Yes:
                    return
            cmd = f"AVD,{kind},{channel},,2"
            # The scanner moves off an avoided channel, so remember it for
            # REMOVE AVOID rather than targeting whatever is displayed next.
            self.last_avoided = (kind, channel, name)
            set_text(self.unavoid_btn, f"REMOVE AVOID: {name}"[:40])
        elif action == "unavoid":
            if self.last_avoided:
                kind, channel, name = self.last_avoided
                question = f"Remove the avoid from the last avoided channel?\n\n{name}"
            elif channel and kind:
                name = self.fields["Channel"].text()
                question = ("No channel has been avoided this session.\n"
                            f"Remove any avoid from the currently displayed channel?\n\n{name}")
            else:
                kind = None
            if kind and confirm:
                reply = QMessageBox.question(self, "Confirm remove avoid", question)
                if reply != QMessageBox.StandardButton.Yes:
                    return
            if kind:
                cmd = f"AVD,{kind},{channel},,3"
                self.last_avoided = None
                set_text(self.unavoid_btn, "REMOVE AVOID")
        if not cmd:
            self.command_reply("No compatible channel/system index available.")
            return
        self.thread.send_command(cmd)
        self.command_reply("QUEUED: " + cmd)

    # ---- Waterfall ------------------------------------------------------
    # Key sequences from the SDS100/SDS200 Waterfall manual. Key codes are from
    # Remote Command Specification V2.00: A/B/C are Soft Keys 1/2/3.
    WATERFALL_ACTIONS = {
        "exit": (("A",), "To Scan: exit waterfall and resume scanning (Soft Key 1)"),
        "span": (("B",), "Change span (Soft Key 2)"),
        "hold": (("C",), "Hold / Sweep: freeze or resume the display (Soft Key 3)"),
        "step": (("F", "A"), "Change step size (FUNC + Soft Key 1)"),
        "maxhold": (("F", "B"), "Max Hold on/off (FUNC + Soft Key 2)"),
        "center": (("F", "C"), "Move marker to center frequency, MF→CF (FUNC + Soft Key 3)"),
        "tune_down": (("<",), "Marker down one step (knob left)"),
        "tune_up": ((">",), "Marker up one step (knob right)"),
        "fast_down": (("F", "<"), "Marker down fast (FUNC + knob left)"),
        "fast_up": (("F", ">"), "Marker up fast (FUNC + knob right)"),
        "display": (("F", "9"), "Open FFT / waterfall split setting (FUNC + 9)"),
        "gain": (("F", "0"), "Open RF gain setting (FUNC + 0)"),
        "confirm": (("E",), "E / YES: confirm a setting (on the waterfall screen, E quick-saves the frequency)"),
    }
    # SDS100 receive coverage in MHz (from the SDS100 specifications).
    SDS100_BANDS = ((25, 512), (758, 824), (849, 869), (894, 960), (1240, 1300))

    def build_waterfall_window(self):
        """The waterfall is a separate, maximizable window (View → Waterfall…).

        Graph on the left, which takes all extra space when the window is
        enlarged; controls on the right in a scrollable column.
        """
        window = WaterfallWindow(self)
        window.setObjectName("waterfallWindow")
        window.setWindowTitle(f"SDS100 Waterfall — SDS100 Monitor v{VERSION}")
        icon_file = Path(__file__).with_name("sds100-monitor.svg")
        if icon_file.exists():
            window.setWindowIcon(QIcon(str(icon_file)))
        window.resize(1250, 760)
        outer = QHBoxLayout(window)
        splitter = QSplitter(Qt.Orientation.Horizontal)
        splitter.setChildrenCollapsible(False)
        graph_side_widget = QWidget()
        graph_side = QVBoxLayout(graph_side_widget)
        graph_side.setContentsMargins(0, 0, 0, 0)
        controls_scroll = QScrollArea()
        controls_scroll.setWidgetResizable(True)
        controls_scroll.setMinimumWidth(430)
        controls = QWidget()
        controls_scroll.setWidget(controls)
        splitter.addWidget(graph_side_widget)
        splitter.addWidget(controls_scroll)
        splitter.setStretchFactor(0, 1)
        splitter.setStretchFactor(1, 0)
        splitter.setSizes([800, 450])
        outer.addWidget(splitter)
        self.waterfall_window = window
        self.waterfall_splitter = splitter
        self.build_waterfall_panel(QVBoxLayout(controls), graph_side)
        # Re-evaluate graph polling when the window is shown or hidden, so the
        # scanner is only asked for graph data while the graph is visible.
        window.visibility_changed.connect(lambda _visible: self.update_graph_polling())

    def open_waterfall_window(self):
        window = self.waterfall_window
        if not window.isVisible():
            if not getattr(self, "waterfall_geometry_restored", False):
                self.waterfall_geometry_restored = True
                geometry = self.settings.value("waterfall/geometry")
                if geometry:
                    window.restoreGeometry(geometry)
                splitter_state = self.settings.value("waterfall/splitter")
                if splitter_state:
                    self.waterfall_splitter.restoreState(splitter_state)
            window.show()
        window.raise_()
        window.activateWindow()

    def build_waterfall_panel(self, layout, graph_side):
        self.waterfall_active = False
        self.connected = False
        self.waterfall_gated = []     # buttons that need waterfall mode
        self.waterfall_entry = []     # buttons that need only a connection
        heading = make_label("WATERFALL CONTROL")
        set_css(heading, "font-size:20px;font-weight:700;color:#8bd6f2;")
        layout.addWidget(heading)
        note = make_label("Controls send the same key presses as the scanner's waterfall screen. "
                      "Most are enabled only while the scanner reports waterfall mode, "
                      "because the same keys do other things (such as holds) in scan mode.")
        note.setWordWrap(True)
        layout.addWidget(note)
        self.waterfall_mode_label = make_label("Waterfall mode: not detected")
        set_css(self.waterfall_mode_label, "font-weight:700;color:#e6a65a;padding:4px;")
        graph_side.addWidget(self.waterfall_mode_label)

        graph_box = QGroupBox("LIVE WATERFALL")
        graph_layout = QVBoxLayout(graph_box)
        self.waterfall_graph = WaterfallGraph()
        self.waterfall_graph.tune_requested.connect(self.tune_waterfall)
        graph_layout.addWidget(self.waterfall_graph, 1)
        graph_row = QHBoxLayout()
        self.waterfall_graph_on = QCheckBox("Show live graph")
        self.waterfall_graph_on.setChecked(
            str(self.settings.value("waterfall/graph_on", "true")).lower() == "true")
        self.waterfall_graph_on.setToolTip(
            "Requests the scanner's graph data (GWF) while waterfall mode is active")
        self.waterfall_graph_on.toggled.connect(self.update_graph_polling)
        graph_row.addWidget(self.waterfall_graph_on)
        graph_row.addWidget(make_label("Update rate:"))
        self.waterfall_graph_rate = QComboBox()
        for label, ms in (("4 per second", 250), ("2 per second", 500), ("1 per second", 1000)):
            self.waterfall_graph_rate.addItem(label, ms)
        saved_rate = self.waterfall_graph_rate.findData(
            int(self.settings.value("waterfall/graph_ms", 250)))
        self.waterfall_graph_rate.setCurrentIndex(max(0, saved_rate))
        self.waterfall_graph_rate.currentIndexChanged.connect(self.update_graph_polling)
        graph_row.addWidget(self.waterfall_graph_rate)
        graph_row.addStretch(1)
        graph_hint = make_label("Hover for frequency • double-click to tune")
        set_css(graph_hint, "color:#a5bdd2;")
        graph_row.addWidget(graph_hint)
        graph_layout.addLayout(graph_row)
        graph_side.addWidget(graph_box, 1)

        status = QGroupBox("WATERFALL STATUS (from scanner)")
        status_grid = QGridLayout(status)
        self.wf_fields = {}
        for row, key in enumerate(("Center", "Span", "Range", "Step",
                                   "Modulation", "Marker", "Gain")):
            status_grid.addWidget(make_label(key.upper()), row, 0)
            value = make_label("—")
            set_css(value, "font-size:16px;font-weight:650;")
            value.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
            status_grid.addWidget(value, row, 1)
            self.wf_fields[key] = value
        status_grid.setColumnStretch(1, 1)
        layout.addWidget(status)

        def make(label, tooltip, slot, gated=True, color="#344d71"):
            b = QPushButton(label)
            b.setToolTip(tooltip)
            b.setMinimumHeight(38)
            set_css(b, f"QPushButton {{background:{color}; color:white; font-weight:700;"
                " border-radius:6px; padding:8px;}"
                "QPushButton:hover {border:2px solid #dceeff;}"
                "QPushButton:disabled {background:#414750;color:#9ca4b0;}")
            b.clicked.connect(slot)
            b.setEnabled(False)
            (self.waterfall_gated if gated else self.waterfall_entry).append(b)
            return b

        def action(name, label, color="#344d71"):
            codes, desc = self.WATERFALL_ACTIONS[name]
            return make(label, desc, lambda checked=False: self.waterfall_action(name), True, color)

        enter = QGroupBox("START WATERFALL")
        enter_grid = QGridLayout(enter)
        enter_grid.addWidget(make(
            "START WATERFALL (JPM)",
            "Sends JPM,WF_MODE,0. The spec lists WF_MODE but marks its index "
            "'Reserve', so this is untested. The reply (OK or NG) appears below.",
            self.enter_waterfall_jpm, gated=False, color="#1b8a5a"), 0, 0, 1, 3)
        enter_grid.addWidget(make_label("Or via search key:"), 1, 0)
        self.waterfall_search_key = QComboBox()
        self.waterfall_search_key.addItems(["SRCH 1", "SRCH 2", "SRCH 3"])
        self.waterfall_search_key.setToolTip(
            "Documented method: assign Waterfall to a search key on the scanner "
            "(Menu → Search for → Set Search Key → Search Key n → Waterfall).")
        enter_grid.addWidget(self.waterfall_search_key, 1, 1)
        enter_grid.addWidget(make(
            "START (FUNC + key)",
            "Sends FUNC then 1, 2 or 3. Works when that search key is set to Waterfall "
            "and the scanner is on a channel.",
            self.enter_waterfall_search_key, gated=False, color="#1b8a5a"), 1, 2)
        layout.addWidget(enter)

        display = QGroupBox("DISPLAY")
        display_grid = QGridLayout(display)
        display_grid.addWidget(action("span", "SPAN"), 0, 0)
        display_grid.addWidget(action("step", "STEP"), 0, 1)
        display_grid.addWidget(action("hold", "HOLD / SWEEP", "#a87d15"), 0, 2)
        display_grid.addWidget(action("maxhold", "MAX HOLD"), 1, 0)
        display_grid.addWidget(action("display", "FFT / WF SPLIT…"), 1, 1)
        display_grid.addWidget(action("gain", "RF GAIN…"), 1, 2)
        display_grid.addWidget(action("exit", "EXIT TO SCAN", "#bd6b23"), 2, 0, 1, 3)
        hint = make_label("FFT / WF SPLIT and RF GAIN open a setting on the scanner: "
                      "choose with the ◀ / ▶ marker buttons, then press CONFIRM (E).")
        hint.setWordWrap(True)
        set_css(hint, "color:#a5bdd2;")
        display_grid.addWidget(hint, 3, 0, 1, 3)
        layout.addWidget(display)

        marker = QGroupBox("MARKER / TUNING")
        marker_grid = QGridLayout(marker)
        marker_grid.addWidget(action("fast_down", "◀◀ FAST"), 0, 0)
        marker_grid.addWidget(action("tune_down", "◀ STEP"), 0, 1)
        marker_grid.addWidget(action("tune_up", "STEP ▶"), 0, 2)
        marker_grid.addWidget(action("fast_up", "FAST ▶▶"), 0, 3)
        marker_grid.addWidget(action("center", "MARKER TO CENTER (MF→CF)"), 1, 0, 1, 2)
        marker_grid.addWidget(action("confirm", "CONFIRM (E)", "#1b8a5a"), 1, 2, 1, 2)
        marker_grid.addWidget(make_label("Marker frequency (MHz):"), 2, 0, 1, 2)
        self.waterfall_freq = QLineEdit()
        self.waterfall_freq.setPlaceholderText("e.g. 154.4300")
        self.waterfall_freq.returnPressed.connect(self.set_waterfall_marker)
        marker_grid.addWidget(self.waterfall_freq, 2, 2)
        marker_grid.addWidget(make(
            "SET", "Types the frequency on the keypad and presses E, which moves the marker.",
            self.set_waterfall_marker), 2, 3)
        layout.addWidget(marker)

        self.waterfall_override = QCheckBox(
            "Allow waterfall keys even when waterfall mode isn't detected")
        self.waterfall_override.setToolTip(
            "Detection relies on the scanner's status report. If the controls stay "
            "disabled while the waterfall is on screen, tick this. In scan mode these "
            "keys act as System / Department / Channel hold.")
        self.waterfall_override.toggled.connect(self.update_waterfall_controls)
        layout.addWidget(self.waterfall_override)
        self.waterfall_feedback = make_label("Connect to enable waterfall controls.")
        self.waterfall_feedback.setWordWrap(True)
        layout.addWidget(self.waterfall_feedback)
        layout.addStretch(1)

    def update_waterfall_controls(self, *_):
        for b in self.waterfall_entry:
            b.setEnabled(self.connected)
        allowed = self.connected and (self.waterfall_active or self.waterfall_override.isChecked())
        for b in self.waterfall_gated:
            b.setEnabled(allowed)
        self.waterfall_freq.setEnabled(allowed)

    def update_waterfall_status(self, root):
        """Read waterfall details from GSI (elements per spec V2.00)."""
        band = root.find("WaterfallBand")
        settings = root.find("WaterfallSettings")
        mode_text = (root.attrib.get("Mode", "") + " " + root.attrib.get("V_Screen", "")).lower()
        active = band is not None or "waterfall" in mode_text
        lower, upper = self.attr(band, "Lower"), self.attr(band, "Upper")
        values = {
            "Center": self.attr(band, "Center"),
            "Span": self.attr(band, "Span"),
            "Range": f"{lower} – {upper}" if band is not None else "—",
            "Step": self.attr(band, "Step"),
            "Modulation": self.attr(band, "Mod"),
            "Marker": self.attr(settings, "MF"),
            "Gain": self.attr(settings, "Gain"),
        }
        for key, value in values.items():
            set_text(self.wf_fields[key], value or "—")
        if active and band is not None:
            self.waterfall_graph.set_band(parse_mhz(lower), parse_mhz(upper),
                                          parse_mhz(self.attr(settings, "MF")),
                                          parse_step_mhz(self.attr(band, "Step")))
        else:
            self.waterfall_graph.set_band(None, None, None, None)
        if active != self.waterfall_active:
            self.waterfall_active = active
            if active:
                set_text(self.waterfall_mode_label, "Waterfall mode: ACTIVE")
                set_css(self.waterfall_mode_label, "font-weight:700;color:#52dc95;padding:4px;")
            else:
                set_text(self.waterfall_mode_label, "Waterfall mode: not detected")
                set_css(self.waterfall_mode_label, "font-weight:700;color:#e6a65a;padding:4px;")
            self.update_waterfall_controls()
            self.update_graph_polling()

    def update_graph_polling(self, *_):
        """Poll GWF only while connected, in waterfall mode, with the graph on."""
        self.settings.setValue("waterfall/graph_on", self.waterfall_graph_on.isChecked())
        self.settings.setValue("waterfall/graph_ms", self.waterfall_graph_rate.currentData())
        tester = getattr(self, "antenna_test", None)
        wanted = bool(self.connected and self.waterfall_active
                      and ((self.waterfall_graph_on.isChecked()
                            and self.waterfall_window.isVisible())
                           or (tester is not None and tester.capturing)))
        if self.thread and self.thread.isRunning():
            self.thread.graph_ms = self.waterfall_graph_rate.currentData()
            self.thread.graph_enabled = wanted
        if not self.waterfall_graph_on.isChecked() and self.waterfall_active:
            self.waterfall_graph.clear("Live graph is off")

    def tune_waterfall(self, mhz):
        """Double-click on the graph: type the frequency and press E."""
        if not self.waterfall_freq.isEnabled():
            return
        try:
            codes = self.waterfall_keys_for(f"{mhz:.4f}")
        except ValueError as exc:
            self.command_reply(str(exc))
            return
        set_text(self.waterfall_freq, f"{mhz:.4f}")
        self.send_key_sequence(codes, "Waterfall marker → " + "".join(codes[:-1]) + " MHz")

    def waterfall_action(self, name):
        codes, desc = self.WATERFALL_ACTIONS[name]
        self.send_key_sequence(codes, f"Waterfall: {desc}")

    def enter_waterfall_jpm(self):
        if not self.thread or not self.thread.isRunning():
            return
        self.thread.send_command("JPM,WF_MODE,0")
        self.command_reply("QUEUED: JPM,WF_MODE,0 (untested; watch for OK or NG)")

    def enter_waterfall_search_key(self):
        key = str(self.waterfall_search_key.currentIndex() + 1)
        self.send_key_sequence(("F", key), f"Start waterfall via FUNC + SRCH {key}")

    @classmethod
    def validate_mhz(cls, text):
        """Return a frequency in MHz within SDS100 coverage, or raise ValueError."""
        text = str(text).strip().lower().removesuffix("mhz").strip()
        if not text or text.count(".") > 1 or not all(c.isdigit() or c == "." for c in text):
            raise ValueError("Enter a frequency in MHz, for example 154.4300.")
        mhz = float(text)
        if not any(low <= mhz <= high for low, high in cls.SDS100_BANDS):
            bands = ", ".join(f"{a}–{b}" for a, b in cls.SDS100_BANDS)
            raise ValueError(f"{mhz:g} MHz is outside SDS100 coverage ({bands} MHz).")
        return mhz

    @classmethod
    def waterfall_keys_for(cls, text):
        """Return keypad codes for a marker frequency, or raise ValueError."""
        mhz = cls.validate_mhz(text)
        digits = f"{mhz:.4f}".rstrip("0").rstrip(".")
        return tuple(digits) + ("E",)

    def set_waterfall_marker(self):
        try:
            codes = self.waterfall_keys_for(self.waterfall_freq.text())
        except ValueError as exc:
            QMessageBox.warning(self, "Marker frequency", str(exc))
            return
        if not self.waterfall_freq.isEnabled():
            return
        self.send_key_sequence(codes, "Waterfall marker → " + "".join(codes[:-1]) + " MHz")

    def build_keypad(self, layout):
        heading = make_label("SDS100 KEYPAD • REMOTE KEY PRESSES")
        set_css(heading, "font-size:20px;font-weight:700;color:#8bd6f2;")
        layout.addWidget(heading)
        help_label = make_label(
            "Use the keypad as you would the scanner buttons. "
            "The ◀ / ▶ controls rotate the scanner knob; the center "
            "button presses it. Keypad operations can change scanner settings.")
        help_label.setWordWrap(True)
        layout.addWidget(help_label)
        dial_box = QGroupBox("ROTARY KNOB")
        dial_row = QHBoxLayout(dial_box)
        dial_row.addStretch(1)
        self.dial = RotaryDial()
        self.dial.activated.connect(self.send_key)
        self.dial.setEnabled(False)
        dial_row.addWidget(self.dial, 1)
        dial_row.addStretch(1)
        layout.addWidget(dial_box, 1)
        panel = QGroupBox("KEYPAD")
        grid = QGridLayout(panel)
        self.keypad_buttons = []

        def button(label, code, row, col, color="#344d71", span=1):
            b = QPushButton(label)
            b.setMinimumHeight(40)
            b.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            set_css(b, f"QPushButton {{background:{color}; color:white;"
                "font-size:17px;font-weight:700;border-radius:8px;padding:8px;}"
                "QPushButton:hover {border:2px solid #dceeff;}"
                "QPushButton:disabled {background:#414750;color:#9ca4b0;}")
            b.clicked.connect(lambda checked=False, k=code: self.send_key(k))
            b.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            b.customContextMenuRequested.connect(
                lambda point, widget=b, k=code, name=label:
                    self.show_keypad_context_menu(widget, point, k, name))
            b.setEnabled(False)
            grid.addWidget(b, row, col, 1, span)
            self.keypad_buttons.append(b)

        button("SYSTEM", "A", 0, 0, "#2167b1")
        button("DEPT", "B", 0, 1, "#2167b1")
        button("CHANNEL", "C", 0, 2, "#2167b1")
        button("MENU", "M", 1, 0, "#7654a6")
        button("FUNC", "F", 1, 1, "#7654a6")
        button("AVOID", "L", 1, 2, "#bd6b23")
        button("◀ KNOB", "<", 2, 0, "#536779")
        button("PUSH KNOB", "^", 2, 1, "#536779")
        button("KNOB ▶", ">", 2, 2, "#536779")
        for row, keys in enumerate((("1","2","3"), ("4","5","6"),
                                    ("7","8","9")), start=3):
            for col, key in enumerate(keys):
                button(key, key, row, col)
        button("./NO", ".", 6, 0, "#536779")
        button("0", "0", 6, 1)
        button("E/YES", "E", 6, 2, "#1b8a5a")
        button("REPLAY", "Y", 7, 0, "#536779")
        button("BACKLIGHT", "V", 7, 1, "#536779")
        button("RANGE", "R", 7, 2, "#536779")
        for column in range(3):
            grid.setColumnStretch(column, 1)
        for row in range(8):
            grid.setRowStretch(row, 1)
        layout.addWidget(panel, 3)
        self.keypad_feedback = make_label("Connect to enable keypad.")
        self.keypad_feedback.setWordWrap(True)
        layout.addWidget(self.keypad_feedback)
